window.QUESTION_BANK=[{"id":1,"topic":"概率","question":"在写有2、4、6、7、8、11、12、13的8张卡片中任取2张，两数互质的概率是多少？","options":[{"id":"A","text":"3/28"},{"id":"B","text":"3/4"},{"id":"C","text":"3/14"},{"id":"D","text":"9/14"}],"answer":"D","explanation":"任取2张共有C(8,2)=28种。逐对检验最大公约数，互质的组合有18种，所以概率为18/28=9/14。"},{"id":2,"topic":"概率","question":"有1、2、3、4、5、6厘米长的小棒各1根，任取3根，能拼成三角形的概率是多少？","options":[{"id":"A","text":"1/3"},{"id":"B","text":"1/4"},{"id":"C","text":"1/6"},{"id":"D","text":"7/20"}],"answer":"D","explanation":"任取3根共有C(6,3)=20种。按“两短边之和大于最长边”逐组检验，符合的有7组，所以概率为7/20。"},{"id":3,"topic":"方程应用","question":"网管员小刘负责甲、乙、丙三个机房的巡检工作，三个机房分别每隔2天、4天和7天巡检一次。3月1日三个机房都已巡检，整个3月有几天不用巡检？","options":[{"id":"A","text":"12天"},{"id":"B","text":"14天"},{"id":"C","text":"15天"},{"id":"D","text":"13天"}],"answer":"D","explanation":"甲机房的巡检日在3月共有16天；乙机房的巡检日包含在甲机房内。丙机房巡检日为1、8、15、22、29日，其中8日和22日是新增日期，共有18天要巡检，所以不用巡检的天数为31-18=13天。"},{"id":4,"topic":"概率","question":"有三个自然数，任取两个数相加分别得到8、11、13，任取两个数相乘分别得到15、24、40，求这三个数的平方和。","options":[{"id":"A","text":"52"},{"id":"B","text":"65"},{"id":"C","text":"70"},{"id":"D","text":"98"}],"answer":"D","explanation":"三个数为3、5、8，平方和为3²+5²+8²=98。"},{"id":5,"topic":"容斥原理","question":"某单位组织党员参加党史、党风廉政建设、科学发展观和业务能力四项培训，要求每名党员参加且只参加其中两项。无论如何安排，都有至少5名党员参加的培训完全相同，问该单位至少有多少名党员？","options":[{"id":"A","text":"17"},{"id":"B","text":"21"},{"id":"C","text":"25"},{"id":"D","text":"29"}],"answer":"C","explanation":"四项培训中任选两项共有6种组合。每种组合最多安排4人时共24人，再增加1人必有某一组合至少5人，因此至少25人。"},{"id":6,"topic":"利润经济","question":"某苗木公司准备出售一批苗木。如果每株以4元出售，可卖出20万株；单价每提高0.4元，就会少卖1万株。问在最佳定价情况下，公司最大收入是多少万元？","options":[{"id":"A","text":"60"},{"id":"B","text":"80"},{"id":"C","text":"90"},{"id":"D","text":"100"}],"answer":"C","explanation":"设提价x次，收入为(4+0.4x)(20-x)万元。该二次函数在x=5时取得最大值90万元。"},{"id":7,"topic":"容斥原理","question":"某社团46人，其中35人爱好戏剧、30人爱好体育、38人爱好写作、40人爱好收藏。至少有多少人同时喜欢这4项活动？","options":[{"id":"A","text":"5人"},{"id":"B","text":"6人"},{"id":"C","text":"7人"},{"id":"D","text":"8人"}],"answer":"A","explanation":"四项爱好人数和为143。若把每人最多先计入3项，46人可容纳138人次，超出的143-138=5人次必须来自同时喜欢4项的人，所以至少5人。"},{"id":8,"topic":"排列组合","question":"有前排6座、后排7座，安排2名不同的人就座。前排中间2座不能坐，且两人不能在同一排相邻。不同坐法有多少种？","options":[{"id":"A","text":"32种"},{"id":"B","text":"44种"},{"id":"C","text":"60种"},{"id":"D","text":"94种"}],"answer":"D","explanation":"可用座位共11个，两人有11×10=110种有序坐法。同排相邻的无序座位对有前排2对、后排6对，共8对；考虑两人顺序要扣16种，得到110-16=94种。"},{"id":9,"topic":"几何问题","question":"某单位准备扩建一个矩形花园。若将花园的长和宽各增加4米，新花园的面积比原来增加40平方米。原花园的周长是多少米？","options":[{"id":"A","text":"12"},{"id":"B","text":"24"},{"id":"C","text":"32"},{"id":"D","text":"40"}],"answer":"A","explanation":"设原长、宽为a、b，则(a+4)(b+4)-ab=40，得a+b=6，原周长为2(a+b)=12米。"},{"id":10,"topic":"方程应用","question":"某次测验有50道判断题，每答对一题得3分，不做或答错一题倒扣1分。某学生共得82分，问答对题数与答错题数（包括未作答）相差多少？","options":[{"id":"A","text":"19"},{"id":"B","text":"18"},{"id":"C","text":"17"},{"id":"D","text":"16"}],"answer":"D","explanation":"设答对x题，则3x-(50-x)=82，解得x=33；其余17题，相差16题。"},{"id":11,"topic":"数论问题","question":"一个四位数分别能被15、12和10整除，且被这三个数整除所得三个商的和为1365。这个四位数的四个数字之和是多少？","options":[{"id":"A","text":"12"},{"id":"B","text":"14"},{"id":"C","text":"15"},{"id":"D","text":"16"}],"answer":"C","explanation":"设该数为n，则n/15+n/12+n/10=n/4=1365，所以n=5460，数字和为15。"},{"id":12,"topic":"比例百分数","question":"某公司去年有830名员工。今年男员工比去年减少6%，女员工比去年增加5%，员工总数增加3人。今年男员工有多少人？","options":[{"id":"A","text":"329人"},{"id":"B","text":"350人"},{"id":"C","text":"371人"},{"id":"D","text":"504人"}],"answer":"A","explanation":"设去年男员工x人，则女员工830-x人。0.94x+1.05(830-x)=833，解得去年男员工350人，今年为350×0.94=329人。"},{"id":13,"topic":"方程应用","question":"5个鸡蛋和3个鸭蛋的重量相当于12个鸭蛋。1个鸡蛋相当于几个鸭蛋的重量？","options":[{"id":"A","text":"1"},{"id":"B","text":"2"},{"id":"C","text":"1.5"},{"id":"D","text":"1.8"}],"answer":"D","explanation":"5个鸡蛋相当于9个鸭蛋，所以1个鸡蛋相当于9÷5=1.8个鸭蛋。"},{"id":14,"topic":"比例百分数","question":"去年车间产量850件，今年884件，增长率是多少？","options":[{"id":"A","text":"1%"},{"id":"B","text":"2%"},{"id":"C","text":"4%"},{"id":"D","text":"5%"}],"answer":"C","explanation":"增长量为884-850=34，增长率为34÷850=4%。"},{"id":15,"topic":"排列组合","question":"一部影片在4个单位各放映1场，4个单位的轮映次序有多少种？","options":[{"id":"A","text":"6种"},{"id":"B","text":"12种"},{"id":"C","text":"24种"},{"id":"D","text":"48种"}],"answer":"C","explanation":"4个不同单位的放映顺序是全排列，共4!=24种。"},{"id":16,"topic":"计数问题","question":"商场活动：满300减180、满200减100、满100减40，不参加活动可打五五折。购买360元、220元、150元商品各1件，最少付多少元？","options":[{"id":"A","text":"360元"},{"id":"B","text":"382.5元"},{"id":"C","text":"401.6元"},{"id":"D","text":"415元"}],"answer":"B","explanation":"逐件取更优惠方式：360元用满减付180元；220元用满减付120元；150元打五五折付82.5元。合计382.5元。"},{"id":17,"topic":"方程应用","question":"甲、乙两数之和为456，甲数末位是5，去掉末位5所得数等于乙。甲数是多少？","options":[{"id":"A","text":"155"},{"id":"B","text":"415"},{"id":"C","text":"355"},{"id":"D","text":"215"}],"answer":"B","explanation":"设乙为x，则甲为10x+5。由10x+5+x=456，解得x=41，因此甲为415。"},{"id":18,"topic":"比例百分数","question":"a比b大20%，b比c大25%，则a比c大多少？","options":[{"id":"A","text":"40%"},{"id":"B","text":"50%"},{"id":"C","text":"60%"},{"id":"D","text":"30%"}],"answer":"B","explanation":"a=1.2b，b=1.25c，所以a=1.5c，即a比c大50%。"},{"id":19,"topic":"数列规律","question":"1/5，1/8，1/11，1/14，（ ）。","options":[{"id":"A","text":"1/15"},{"id":"B","text":"1/17"},{"id":"C","text":"1/16"},{"id":"D","text":"1/18"}],"answer":"B","explanation":"分母依次增加3，所以下一项为1/17。"},{"id":20,"topic":"数论问题","question":"一个小于200的自然数，除以11余8，除以13余10。这个数是多少？","options":[{"id":"A","text":"140"},{"id":"B","text":"126"},{"id":"C","text":"154"},{"id":"D","text":"168"}],"answer":"A","explanation":"把候选数写成11k+8，逐个检验模13的余数。140÷11余8，140÷13余10，且140小于200。"},{"id":21,"topic":"容斥原理","question":"三位专家为10幅作品投票，每位专家各投5票，且每幅作品都至少有一位专家投票。三位专家都投票的作品为A等，两位专家投票的作品为B等，仅一位专家投票的作品为C等。下列说法正确的是哪一项？","options":[{"id":"A","text":"A等和B等共6幅"},{"id":"B","text":"B等和C等共7幅"},{"id":"C","text":"A等最多有5幅"},{"id":"D","text":"A等比C等少5幅"}],"answer":"D","explanation":"本题考查容斥原理。先计算各集合人数之和，再扣除重复部分或使用最不利情况。计算结果为“A等比C等少5幅”，因此选择D。"},{"id":22,"topic":"概率","question":"8名网球选手平均分成两组，每组4人。甲、乙两名选手不在同一组的概率是多少？","options":[{"id":"A","text":"3/7"},{"id":"B","text":"5/7"},{"id":"C","text":"4/7"},{"id":"D","text":"6/7"}],"answer":"C","explanation":"先固定甲所在的组。剩余7个位置中，有4个位置属于另一组，所以乙与甲不同组的概率是4/7。"},{"id":23,"topic":"方程应用","question":"最小的两位数、最小的三位数和最小的四位数之和是多少？","options":[{"id":"A","text":"1010"},{"id":"B","text":"2100"},{"id":"C","text":"11100"},{"id":"D","text":"1110"}],"answer":"D","explanation":"10+100+1000=1110。"},{"id":24,"topic":"排列组合","question":"制作一面国旗要用红、黄、蓝3种颜色的布。制作4面完全相同的国旗，至少需要多少种颜色的布？","options":[{"id":"A","text":"3种"},{"id":"B","text":"2种"},{"id":"C","text":"4种"},{"id":"D","text":"5种"}],"answer":"A","explanation":"四面国旗完全相同，可以反复使用同样的3种颜色，不会因数量增加而增加颜色种类。"},{"id":25,"topic":"数列规律","question":"1，8，9，4，（ ），1/6。","options":[{"id":"A","text":"3"},{"id":"B","text":"2"},{"id":"C","text":"1"},{"id":"D","text":"1/3"}],"answer":"C","explanation":"各项可写为1¹、2³、3²、4¹、5⁰、6⁻¹，因此空缺项为1。"},{"id":26,"topic":"方程应用","question":"某上有8只鸟，猎人开枪打死2只，问某上还剩几只鸟？","options":[{"id":"A","text":"0"},{"id":"B","text":"2"},{"id":"C","text":"6"},{"id":"D","text":"8"}],"answer":"A","explanation":"本题考查方程应用。设未知数，把题干中的等量关系翻译成方程并求解。计算结果为“0”，因此选择A。"},{"id":27,"topic":"数列规律","question":"3，4，8，24，88，（ ）。","options":[{"id":"A","text":"344"},{"id":"B","text":"332"},{"id":"C","text":"166"},{"id":"D","text":"164"}],"answer":"A","explanation":"本题考查数列规律。比较相邻项的差、比或拆分奇偶位置，确定稳定变化规律。计算结果为“344”，因此选择A。"},{"id":28,"topic":"数列规律","question":"28，17，6，（ ），8/7。","options":[{"id":"A","text":"3/2"},{"id":"B","text":"1"},{"id":"C","text":"0"},{"id":"D","text":"2"}],"answer":"D","explanation":"〗28=3“+1.17=4:+1 6=5'+1 2=6%1 8/7=7\"+1门 “"},{"id":29,"topic":"数论问题","question":"某电器工作功耗为370瓦，待机功耗为37瓦。周一9:30至17:00处于工作状态，其余时间断电；周二9:00至24:00处于待机状态，其余时间断电。周一耗电量是周二的多少倍？","options":[{"id":"A","text":"6"},{"id":"B","text":"7"},{"id":"C","text":"8"},{"id":"D","text":"5"}],"answer":"D","explanation":"周一耗电量为370×7.5，周二耗电量为37×15，二者之比为5。"},{"id":30,"topic":"方程应用","question":"一个人去书店买了一本书和一本杂志，付款时把书价的十位数和个位数看反了，付了21元。售货员说应付39元。书比杂志贵多少元？","options":[{"id":"A","text":"20"},{"id":"B","text":"22"},{"id":"C","text":"23"},{"id":"D","text":"24"}],"answer":"C","explanation":"本题考查方程应用。设未知数，把题干中的等量关系翻译成方程并求解。计算结果为“23”，因此选择C。"},{"id":31,"topic":"比例百分数","question":"两个城市中心的距离在比例尺为1:100000的地图上为16.8厘米，两地实际距离是多少公里？","options":[{"id":"A","text":"1.68"},{"id":"B","text":"16.8"},{"id":"C","text":"168"},{"id":"D","text":"1680"}],"answer":"B","explanation":"本题考查比例百分数。把基准量设为1份或100%，按对应比例换算。计算结果为“16.8”，因此选择B。"},{"id":32,"topic":"几何问题","question":"在一块长25公里、宽8公里的长方形区域内设置哨塔，每个哨塔的监视半径为5公里。若要求区域内每个角落都能被监视到，至少需要设置多少个哨塔？","options":[{"id":"A","text":"7"},{"id":"B","text":"6"},{"id":"C","text":"5"},{"id":"D","text":"4"}],"answer":"C","explanation":"本题考查几何问题。画出关键尺寸，代入相应的周长、面积或体积公式。计算结果为“5”，因此选择C。"},{"id":33,"topic":"比例百分数","question":"某单位原有本科、研究生学历职工人数之比为7∶5。上半年招聘本科生后，两类人数之比变为3∶1；下半年引进研究生后，又变为15∶8。全年引进的本科生比研究生多15人。原有两类职工共多少人？","options":[{"id":"A","text":"32人"},{"id":"B","text":"36人"},{"id":"C","text":"40人"},{"id":"D","text":"44人"}],"answer":"B","explanation":"设原人数为7k、5k。招聘本科生8k人后变为15k∶5k；再引进3k名研究生后变为15∶8。由8k-3k=15得k=3，原有12k=36人。"},{"id":34,"topic":"利润经济","question":"商业街发放满50减10元、满100减30元、满200减60元优惠券。商户共核销15.6万张，优惠总额的75%可抵租金，最终抵扣租金219万元。消费者实际支付金额的最低值在哪个范围？","options":[{"id":"A","text":"低于750万元"},{"id":"B","text":"750～800万元"},{"id":"C","text":"800～850万元"},{"id":"D","text":"超过850万元"}],"answer":"C","explanation":"优惠总额为219÷75%=292万元。要让实付最低，应优先使用满100减30的券：可由8.8万张10元券和6.8万张30元券组成。最低实付为8.8×40+6.8×70=828万元。"},{"id":35,"topic":"计数问题","question":"某村有756名居民需要乘车，车辆有20座中巴和30座大巴。按车辆总数最少的原则安排，最少需要多少辆大巴？","options":[{"id":"A","text":"23辆"},{"id":"B","text":"29辆"},{"id":"C","text":"32辆"},{"id":"D","text":"26辆"}],"answer":"D","explanation":"大巴载客量更大。756÷30=25余6，因此至少需要26辆大巴；25辆最多载750人，不够。"},{"id":36,"topic":"计数问题","question":"某地10户农户共申请25万元贷款。每户申请额都是1000元的整数倍，各户金额互不相同，最高额不超过最低额的2倍。最低申请额最少可能是多少万元？","options":[{"id":"A","text":"1.6万元"},{"id":"B","text":"1.44万元"},{"id":"C","text":"1.76万元"},{"id":"D","text":"1.92万元"}],"answer":"A","explanation":"把金额按千元计。最低额若为15，另外9个数最多取22～30，总和为234，加15只有249，不足250；最低额为16时可以配出总和250，因此最少为1.6万元。"},{"id":37,"topic":"几何问题","question":"用三个互相垂直的平面切一个圆柱形蛋糕，最多能切成多少块？","options":[{"id":"A","text":"7块"},{"id":"B","text":"8块"},{"id":"C","text":"9块"},{"id":"D","text":"10块"}],"answer":"B","explanation":"第一刀分成2块，第二刀与第一刀垂直可分成4块，第三刀再与前两刀垂直，可把4块各分为两半，共8块。"},{"id":38,"topic":"年龄问题","question":"今年哥哥和弟弟的年龄和为55岁。曾有一年，哥哥当时的年龄等于弟弟今年的年龄，并且当时哥哥年龄是弟弟年龄的2倍。哥哥今年多少岁？","options":[{"id":"A","text":"30岁"},{"id":"B","text":"36岁"},{"id":"C","text":"33岁"},{"id":"D","text":"39岁"}],"answer":"C","explanation":"设哥哥今年x岁，弟弟55-x岁。回到哥哥为55-x岁时，弟弟为110-3x岁。由55-x=2(110-3x)，解得x=33。"},{"id":39,"topic":"方程应用","question":"计算：999×999+1999。","options":[{"id":"A","text":"900000"},{"id":"B","text":"1100000"},{"id":"C","text":"1200000"},{"id":"D","text":"1000000"}],"answer":"D","explanation":"999×999=(1000-1)²=998001，再加1999恰好等于1000000。"},{"id":40,"topic":"工程问题","question":"修建一座水库，甲村单独投资还缺92万元，乙村单独投资还缺88万元，两村合作投资仍缺20万元。修建水库共需多少万元？","options":[{"id":"A","text":"160万元"},{"id":"B","text":"144万元"},{"id":"C","text":"176万元"},{"id":"D","text":"192万元"}],"answer":"A","explanation":"设总投资为x万元，则甲村可出x-92，乙村可出x-88。合作仍缺20，故(x-92)+(x-88)=x-20，解得x=160。"},{"id":41,"topic":"方程应用","question":"最小的两位数、最小的三位数和最小的四位数之和是多少？","options":[{"id":"A","text":"999"},{"id":"B","text":"1110"},{"id":"C","text":"1221"},{"id":"D","text":"1332"}],"answer":"B","explanation":"最小的两位数是10，最小的三位数是100，最小的四位数是1000，三者之和为1110。"},{"id":42,"topic":"工程问题","question":"一份稿件，小王单独打需8小时，老张单独打需6小时。两人一起打字，中途老张停了1小时。完成时小王工作了多少小时？","options":[{"id":"A","text":"3小时"},{"id":"B","text":"5小时"},{"id":"C","text":"4小时"},{"id":"D","text":"6小时"}],"answer":"C","explanation":"设小王工作x小时，则老张工作x-1小时。列式x/8+(x-1)/6=1，解得x=4。"},{"id":43,"topic":"方程应用","question":"纽约时间比香港时间晚13小时。纽约4月1日20:00通话时，香港是几点？","options":[{"id":"A","text":"3月2日9:00"},{"id":"B","text":"5月2日9:00"},{"id":"C","text":"6月2日9:00"},{"id":"D","text":"4月2日9:00"}],"answer":"D","explanation":"香港时间比纽约早13小时，20:00加13小时为次日9:00。"},{"id":44,"topic":"数列规律","question":"找规律：4，7，6，8，8，11，（ ），（ ）。","options":[{"id":"A","text":"10，16"},{"id":"B","text":"9，16"},{"id":"C","text":"11，16"},{"id":"D","text":"12，16"}],"answer":"A","explanation":"奇数位为4、6、8、10，依次加2；偶数位为7、8、11、16，增量依次为1、3、5。"},{"id":45,"topic":"排列组合","question":"数列按（1，3，5）、（2，6，10）、（3，9，15）……排列，第101个数是多少？","options":[{"id":"A","text":"92"},{"id":"B","text":"102"},{"id":"C","text":"112"},{"id":"D","text":"122"}],"answer":"B","explanation":"每3个数为一组，第n组是n、3n、5n。101=3×33+2，是第34组第2个数，即3×34=102。"},{"id":46,"topic":"数列规律","question":"找规律：3，4，8，24，88，（ ）。","options":[{"id":"A","text":"310"},{"id":"B","text":"378"},{"id":"C","text":"344"},{"id":"D","text":"412"}],"answer":"C","explanation":"相邻两项的差依次为1、4、16、64，均为前一个差的4倍，所以下一个差为256，88+256=344。"},{"id":47,"topic":"方程应用","question":"空间中三条不同直线的交点个数可能有哪些？","options":[{"id":"A","text":"0、2"},{"id":"B","text":"2、3"},{"id":"C","text":"0、2、3"},{"id":"D","text":"0、1、2、3"}],"answer":"D","explanation":"三线可互相异面而无交点，也可出现1个、2个或两两相交形成3个不同交点，因此四种数量都可能。"},{"id":48,"topic":"几何问题","question":"一块宽为2a的长方形铁片，两边各向上折起x，形成矩形水槽。x取何值时横截面积最大？","options":[{"id":"A","text":"a/4"},{"id":"B","text":"a/3"},{"id":"C","text":"a/2"},{"id":"D","text":"2a/3"}],"answer":"C","explanation":"横截面积S=x(2a-2x)=-2(x-a/2)²+a²/2，所以x=a/2时面积最大。"},{"id":49,"topic":"概率","question":"一枚均匀硬币连续抛3次，至少有2次正面朝上的概率是多少？","options":[{"id":"A","text":"0/2"},{"id":"B","text":"1/2"},{"id":"C","text":"2/2"},{"id":"D","text":"3/2"}],"answer":"B","explanation":"恰有2次正面有C(3,2)=3种，3次全是正面有1种，共4种；总结果有2³=8种，概率为4/8=1/2。"},{"id":50,"topic":"几何问题","question":"一个长方形被分成3×3的9个小长方形。三个角上小长方形的面积分别为8、12、18，第四个角的面积是多少？","options":[{"id":"A","text":"24"},{"id":"B","text":"30"},{"id":"C","text":"27"},{"id":"D","text":"33"}],"answer":"C","explanation":"设四角面积分别为ac、ad、bc、bd，则ac×bd=ad×bc。第四角面积为12×18÷8=27。"},{"id":51,"topic":"年龄问题","question":"一家三口年龄和为74岁，爸爸比妈妈大2岁，妈妈年龄是孩子的4倍。爸爸多少岁？","options":[{"id":"A","text":"31岁"},{"id":"B","text":"37岁"},{"id":"C","text":"40岁"},{"id":"D","text":"34岁"}],"answer":"D","explanation":"设孩子x岁，则妈妈4x岁、爸爸4x+2岁。x+4x+4x+2=74，得x=8，爸爸34岁。"},{"id":52,"topic":"方程应用","question":"台历连续7天没有翻，这7个日期之和为77。今天是几号？","options":[{"id":"A","text":"15号"},{"id":"B","text":"13号"},{"id":"C","text":"17号"},{"id":"D","text":"19号"}],"answer":"A","explanation":"连续7个日期的中间数等于平均数77÷7=11，所以这7天是8日至14日，今天是15日。"},{"id":53,"topic":"利润经济","question":"某商品按成本价加价40%定价，后按定价的75%出售，每件盈利16元。成本价是多少？","options":[{"id":"A","text":"288元"},{"id":"B","text":"320元"},{"id":"C","text":"352元"},{"id":"D","text":"384元"}],"answer":"B","explanation":"售价为成本的1.4×0.75=1.05倍，利润率为5%。成本价=16÷5%=320元。"},{"id":54,"topic":"方程应用","question":"某校师生共若干人，男女比为7∶3，教师与学生比为2∶8，教师中男女比也为7∶3。男教师有70人，女学生有多少人？","options":[{"id":"A","text":"108人"},{"id":"B","text":"132人"},{"id":"C","text":"120人"},{"id":"D","text":"144人"}],"answer":"C","explanation":"男教师70人对应教师的70%，教师共100人；全校共500人，女性150人。女教师30人，所以女学生为150-30=120人。"},{"id":55,"topic":"排列组合","question":"某病房有15名护士，每班2人，每8小时换班。若把所有两人组合轮换一遍，同一组合再次值班最长需多少天？","options":[{"id":"A","text":"31天"},{"id":"B","text":"39天"},{"id":"C","text":"43天"},{"id":"D","text":"35天"}],"answer":"D","explanation":"两人组合共有C(15,2)=105组，每班8小时，共105×8=840小时，即35天。"},{"id":56,"topic":"方程应用","question":"已知-5<x≤3，-3<y≤5，则xy的取值范围是？","options":[{"id":"A","text":"-25<xy≤15"},{"id":"B","text":"-15<xy<15"},{"id":"C","text":"-25≤xy≤25"},{"id":"D","text":"-25<xy<25"}],"answer":"A","explanation":"正积最大值为3×5=15；负积可以无限接近-25但不能取到。整体范围为-25<xy≤15。"},{"id":57,"topic":"方程应用","question":"下列哪个分数大于4/5且小于5/6？","options":[{"id":"A","text":"7/10"},{"id":"B","text":"10/11"},{"id":"C","text":"49/60"},{"id":"D","text":"28/31"}],"answer":"C","explanation":"4/5=48/60，5/6=50/60，因此49/60严格位于两者之间。"},{"id":58,"topic":"方程应用","question":"三个自然数两两相加分别得到4、7、9，两两相乘分别得到3、6、18。这三个数的平方和是多少？","options":[{"id":"A","text":"41"},{"id":"B","text":"51"},{"id":"C","text":"46"},{"id":"D","text":"56"}],"answer":"C","explanation":"三个数是1、3、6，平方和为1²+3²+6²=46。"},{"id":59,"topic":"概率","question":"从1～9中任取3个不同的数，恰好只有一组相邻数的概率是多少？","options":[{"id":"A","text":"0/2"},{"id":"B","text":"2/2"},{"id":"C","text":"3/2"},{"id":"D","text":"1/2"}],"answer":"D","explanation":"总取法为C(9,3)=84。枚举相邻数对并排除连续三数，可得符合条件的三数组合有42个，所以概率为42/84=1/2。"},{"id":60,"topic":"工程问题","question":"A、B两台机器合作18天完成任务，A、C合作28天完成，A、B、C合作14.4天完成。B、C合作需多少天？","options":[{"id":"A","text":"21天"},{"id":"B","text":"19天"},{"id":"C","text":"23天"},{"id":"D","text":"25天"}],"answer":"A","explanation":"设效率为a、b、c。a+b=1/18，a+c=1/28，a+b+c=1/14.4，先求a，再得b+c=1/21。"},{"id":61,"topic":"容斥原理","question":"某年级100人，20人参加外语组，32人参加计算机组。两组都不参加的人至少有多少？","options":[{"id":"A","text":"43人"},{"id":"B","text":"48人"},{"id":"C","text":"53人"},{"id":"D","text":"58人"}],"answer":"B","explanation":"两组参加人数的并集最多为20+32=52人，因此都不参加的人至少为100-52=48人。"},{"id":62,"topic":"方程应用","question":"数学竞赛共10题，答对1题得8分，答错1题扣5分。小明答完全部题并得41分，他答对几题？","options":[{"id":"A","text":"6题"},{"id":"B","text":"8题"},{"id":"C","text":"7题"},{"id":"D","text":"9题"}],"answer":"C","explanation":"设答对x题，则8x-5(10-x)=41，解得13x=91，x=7。"},{"id":63,"topic":"方程应用","question":"数学竞赛共20题，答对1题得5分，答错或不答扣3分。小明得60分，他答对几题？","options":[{"id":"A","text":"13题"},{"id":"B","text":"17题"},{"id":"C","text":"19题"},{"id":"D","text":"15题"}],"answer":"D","explanation":"设答对x题，则5x-3(20-x)=60，解得8x=120，所以x=15。"},{"id":64,"topic":"行程问题","question":"静水中船以垂直河岸的方向匀速过河，用时T₁。水流动后，船相对水的方向和速度不变，过河用时T₂。两者关系如何？","options":[{"id":"A","text":"T₂>T₁"},{"id":"B","text":"T₂=T₁"},{"id":"C","text":"T₂<T₁"},{"id":"D","text":"无法确定"}],"answer":"B","explanation":"水流只改变沿河方向的位移，不改变船垂直河岸方向的速度分量，所以过河时间不变。"},{"id":65,"topic":"行程问题","question":"甲、乙两车同地同向前往目的地。甲每小时40千米，乙每小时35千米。乙先行20千米后甲出发，甲几小时追上乙？","options":[{"id":"A","text":"3小时"},{"id":"B","text":"4小时"},{"id":"C","text":"5小时"},{"id":"D","text":"6小时"}],"answer":"B","explanation":"甲每小时比乙多行5千米，追上20千米的路程差需要20÷5=4小时。"},{"id":66,"topic":"容斥原理","question":"兄弟从家去学校。弟弟每分钟60米，提前10分钟出发；哥哥每分钟90米，两人同时到校。家到学校多远？","options":[{"id":"A","text":"1620米"},{"id":"B","text":"1980米"},{"id":"C","text":"1800米"},{"id":"D","text":"2160米"}],"answer":"C","explanation":"设哥哥走t分钟，60(t+10)=90t，解得t=20，路程为90×20=1800米。"},{"id":67,"topic":"方程应用","question":"小明有一些巧克力，第一天吃一半，第二天又吃剩下的一半，最后还剩1颗。原有多少颗？","options":[{"id":"A","text":"3颗"},{"id":"B","text":"5颗"},{"id":"C","text":"6颗"},{"id":"D","text":"4颗"}],"answer":"D","explanation":"倒推：第二天吃之前有2颗，第一天吃之前有4颗。"},{"id":68,"topic":"方程应用","question":"小明有一些巧克力，先吃4颗，再把剩下的一半送人，自己还剩18颗。原有多少颗？","options":[{"id":"A","text":"40颗"},{"id":"B","text":"36颗"},{"id":"C","text":"44颗"},{"id":"D","text":"48颗"}],"answer":"A","explanation":"送人前剩36颗，因此原来有36+4=40颗。"},{"id":69,"topic":"比例百分数","question":"两个三角形面积相等，底边之比为7∶8，高之比是多少？","options":[{"id":"A","text":"7∶7"},{"id":"B","text":"8∶7"},{"id":"C","text":"9∶7"},{"id":"D","text":"10∶7"}],"answer":"B","explanation":"面积相等时底×高相等，因此高与底成反比，高之比为8∶7。"},{"id":70,"topic":"排列组合","question":"有4张数字卡片3、4、7、9，任选两张求和，和有多少种不同结果？","options":[{"id":"A","text":"5种"},{"id":"B","text":"7种"},{"id":"C","text":"6种"},{"id":"D","text":"8种"}],"answer":"C","explanation":"六组和分别为7、10、12、11、13、16，互不相同，共6种。"},{"id":71,"topic":"方程应用","question":"如果今天是星期六，那么147天后是星期几？","options":[{"id":"A","text":"星期一"},{"id":"B","text":"星期六"},{"id":"C","text":"星期日"},{"id":"D","text":"星期四"}],"answer":"B","explanation":"147÷7=21，没有余数，所以星期不变。"},{"id":72,"topic":"行程问题","question":"地铁检修车匀速行驶，每6分钟有一列同向地铁从后面追上，每2分钟有一列反向地铁迎面开来。两方向列车速度、发车间隔相同，发车间隔是多少？","options":[{"id":"A","text":"3分钟"},{"id":"B","text":"2分钟"},{"id":"C","text":"4分钟"},{"id":"D","text":"5分钟"}],"answer":"A","explanation":"设列车速度v、检修车速度u、相邻列车距离d，则d/(v-u)=6，d/(v+u)=2。解得u=v/2、d=3v，所以发车间隔d/v=3分钟。"},{"id":73,"topic":"方程应用","question":"小明有88元买35支冰淇淋。买20支巧克力味和15支草莓味还差17元；买15支巧克力味和20支草莓味剩3元。草莓味每支多少元？","options":[{"id":"A","text":"1元"},{"id":"B","text":"2元"},{"id":"C","text":"3元"},{"id":"D","text":"4元"}],"answer":"B","explanation":"设巧克力、草莓单价为x、y。由20x+15y=105、15x+20y=85，解得y=2。"},{"id":74,"topic":"方程应用","question":"3只玩具兔10元，5只玩具熊20元。幼儿园花70元买了18只玩具兔和玩具熊，其中玩具兔有多少只？","options":[{"id":"A","text":"2只"},{"id":"B","text":"4只"},{"id":"C","text":"3只"},{"id":"D","text":"5只"}],"answer":"C","explanation":"设兔有x只，熊18-x只。列式(10/3)x+4(18-x)=70，解得x=3。"},{"id":75,"topic":"方程应用","question":"x、y为正整数，4x+3y=47。下列哪个数可能是y？","options":[{"id":"A","text":"8"},{"id":"B","text":"10"},{"id":"C","text":"11"},{"id":"D","text":"9"}],"answer":"D","explanation":"对选项逐一代入，y=9时4x=20，x=5为正整数。"},{"id":76,"topic":"工程问题","question":"一项植树任务按每天200棵计划45天完成。如果每天多种25%，可提前多少天完成？","options":[{"id":"A","text":"9天"},{"id":"B","text":"8天"},{"id":"C","text":"10天"},{"id":"D","text":"11天"}],"answer":"A","explanation":"总量为200×45。提速后每天种250棵，需要36天，因此提前45-36=9天。"},{"id":77,"topic":"数列规律","question":"找规律：100，81，64，49，36，（ ）。","options":[{"id":"A","text":"23"},{"id":"B","text":"25"},{"id":"C","text":"27"},{"id":"D","text":"29"}],"answer":"B","explanation":"各项依次是10²、9²、8²、7²、6²，下一项是5²=25。"},{"id":78,"topic":"计数问题","question":"在一条长256米的直路一侧植树，每隔1米种1棵，两端都种，共需多少棵？","options":[{"id":"A","text":"231棵"},{"id":"B","text":"283棵"},{"id":"C","text":"257棵"},{"id":"D","text":"309棵"}],"answer":"C","explanation":"间隔数为256÷1=256，棵数比间隔数多1，所以是257棵。"},{"id":79,"topic":"计数问题","question":"一盒乒乓球每次取5个黄球、3个白球，白球正好取完时还剩8个黄球；若每次取7个黄球、3个白球，黄球正好取完时还剩24个白球。盒中共有多少个球？","options":[{"id":"A","text":"238个"},{"id":"B","text":"290个"},{"id":"C","text":"316个"},{"id":"D","text":"264个"}],"answer":"D","explanation":"设两种取法分别进行k、m次，则黄球5k+8=7m，白球3k=3m+24。解得m=24、k=32，黄球168个、白球96个，共264个。"},{"id":80,"topic":"利润经济","question":"某商品进价80元，按90元可卖400件。售价每提高1元，销量减少20件。利润最大时应定价多少元？","options":[{"id":"A","text":"95元"},{"id":"B","text":"85元"},{"id":"C","text":"105元"},{"id":"D","text":"115元"}],"answer":"A","explanation":"设提价x元，利润为(10+x)(400-20x)，整理为开口向下的二次函数，在x=5时最大，所以定价95元。"},{"id":81,"topic":"工程问题","question":"甲单独完成工程需40天，乙需24天。乙先做12天后由甲完成，甲还需多少天？","options":[{"id":"A","text":"18天"},{"id":"B","text":"20天"},{"id":"C","text":"22天"},{"id":"D","text":"24天"}],"answer":"B","explanation":"乙12天完成12/24=1/2，剩余1/2由甲完成，需要40×1/2=20天。"},{"id":82,"topic":"行程问题","question":"一列长90米的火车以30米/秒通过长1200米的隧道，需要多少秒？","options":[{"id":"A","text":"39秒"},{"id":"B","text":"47秒"},{"id":"C","text":"43秒"},{"id":"D","text":"51秒"}],"answer":"C","explanation":"火车完全通过需行驶1200+90=1290米，用时1290÷30=43秒。"},{"id":83,"topic":"方程应用","question":"正数a、b的算术平均数是几何平均数的2倍，则a/b的值最接近哪个数？","options":[{"id":"A","text":"13"},{"id":"B","text":"15"},{"id":"C","text":"16"},{"id":"D","text":"14"}],"answer":"D","explanation":"令t=√(a/b)，由(a+b)/2=2√(ab)得t²-4t+1=0。较大的比值(2+√3)²≈13.93，最接近14。"},{"id":84,"topic":"方程应用","question":"一本300页的书里出现了几次1? aK","options":[{"id":"A","text":"120"},{"id":"B","text":"140"},{"id":"C","text":"160"},{"id":"D","text":"180"}],"answer":"B","explanation":"本题考查方程应用。设未知数，把题干中的等量关系翻译成方程并求解。计算结果为“140”，因此选择B。"},{"id":85,"topic":"利润经济","question":"一年前某股票价格为10元，一年内税后股息为0.25元，现在股价为12元。不计交易费用，一年收益率是多少？","options":[{"id":"A","text":"20.25%"},{"id":"B","text":"22.5%"},{"id":"C","text":"24.75%"},{"id":"D","text":"27%"}],"answer":"B","explanation":"收益包括价差2元和股息0.25元，总收益2.25元，相对最初10元的收益率为22.5%。"},{"id":86,"topic":"比例百分数","question":"有40个气球，30%是红色，其余为黄色；黄色气球中1/4系了绳子。未系绳的黄色气球有多少个？","options":[{"id":"A","text":"19个"},{"id":"B","text":"23个"},{"id":"C","text":"21个"},{"id":"D","text":"25个"}],"answer":"C","explanation":"黄色有40×70%=28个，未系绳占3/4，所以有28×3/4=21个。"},{"id":87,"topic":"概率","question":"两个独立安全系统的报警概率分别为0.93和0.96。至少一个系统报警的概率是多少？","options":[{"id":"A","text":"0.8972"},{"id":"B","text":"1.0972"},{"id":"C","text":"1.1972"},{"id":"D","text":"0.9972"}],"answer":"D","explanation":"用对立事件：1-(1-0.93)(1-0.96)=1-0.07×0.04=0.9972。"},{"id":88,"topic":"方程应用","question":"用绳子测井深：绳子三折后长出井口4米，四折后长出井口1米。井深多少米？","options":[{"id":"A","text":"8米"},{"id":"B","text":"7米"},{"id":"C","text":"9米"},{"id":"D","text":"10米"}],"answer":"A","explanation":"设井深d、绳长L，则L=3(d+4)=4(d+1)，解得d=8。"},{"id":89,"topic":"利润经济","question":"2013年1—6月商品房销售面积同比增长28.7%，销售额同比增长43.2%。商品房平均销售价格同比约增长多少？","options":[{"id":"A","text":"10.17%"},{"id":"B","text":"11.3%"},{"id":"C","text":"12.43%"},{"id":"D","text":"13.56%"}],"answer":"B","explanation":"平均价=销售额÷销售面积，增幅为1.432÷1.287-1≈11.3%。"},{"id":90,"topic":"方程应用","question":"某省2006年城镇固定资产投资中，第一、第二、第三产业投资分别为15.45亿元、3439.08亿元、4019.17亿元。三者合计多少亿元？","options":[{"id":"A","text":"6726.33亿元"},{"id":"B","text":"8221.07亿元"},{"id":"C","text":"7473.7亿元"},{"id":"D","text":"8968.44亿元"}],"answer":"C","explanation":"直接相加：15.45+3439.08+4019.17=7473.70亿元。"},{"id":91,"topic":"行程问题","question":"两校相距2760米，甲、乙分别以70米/分、110米/分从两校同时出发，到对方学校后立即返回。从出发到第二次相遇需多少分钟？","options":[{"id":"A","text":"41分钟"},{"id":"B","text":"51分钟"},{"id":"C","text":"56分钟"},{"id":"D","text":"46分钟"}],"answer":"D","explanation":"第二次相遇时两人合计行程为3个全程，即3×2760米。用时为8280÷(70+110)=46分钟。"},{"id":92,"topic":"数列规律","question":"找规律：8/9，2/3，1/2，3/8，9/32，（ ）。","options":[{"id":"A","text":"27/128"},{"id":"B","text":"24/128"},{"id":"C","text":"30/128"},{"id":"D","text":"33/128"}],"answer":"A","explanation":"每一项都是前一项乘3/4，所以下一项为9/32×3/4=27/128。"},{"id":93,"topic":"概率","question":"7个白球、3个红球随机分给5个人，每人2个球。3个红球分别由3个人得到的概率是多少？","options":[{"id":"A","text":"1/3"},{"id":"B","text":"2/3"},{"id":"C","text":"3/3"},{"id":"D","text":"4/3"}],"answer":"B","explanation":"把10个位置分成5组，每组2个。总选法C(10,3)=120；从5人中选3人且每人选1个位置，有C(5,3)×2³=80种，概率为80/120=2/3。"},{"id":94,"topic":"计数问题","question":"钉子按4个0.25元买入，再按3个0.22元卖出，共获利2.6元。一共买了多少个钉子？","options":[{"id":"A","text":"216个"},{"id":"B","text":"264个"},{"id":"C","text":"240个"},{"id":"D","text":"288个"}],"answer":"C","explanation":"每个进价0.25÷4元，售价0.22÷3元，单个利润为13/1200元。2.6÷(13/1200)=240。"},{"id":95,"topic":"年龄问题","question":"一家三口年龄和74岁，妈妈比爸爸小2岁，妈妈年龄是儿子的4倍。三人各多少岁？","options":[{"id":"A","text":"爸爸34岁、妈妈32岁、儿子8岁"},{"id":"B","text":"爸爸36岁、妈妈34岁、儿子4岁"},{"id":"C","text":"爸爸32岁、妈妈30岁、儿子12岁"},{"id":"D","text":"爸爸38岁、妈妈36岁、儿子0岁"}],"answer":"A","explanation":"设儿子x岁，则妈妈4x岁、爸爸4x+2岁。9x+2=74，解得x=8。"},{"id":96,"topic":"利润经济","question":"某国1995年国民总收入为105亿元，总储蓄为75亿元。储蓄率约为多少？","options":[{"id":"A","text":"71.4%"},{"id":"B","text":"64.26%"},{"id":"C","text":"78.54%"},{"id":"D","text":"85.68%"}],"answer":"A","explanation":"储蓄率=总储蓄÷国民总收入=75÷105≈71.4%。"},{"id":97,"topic":"方程应用","question":"车队运货：每车运3500千克还剩5000千克；每车运4000千克还剩500千克。车队有多少辆车？","options":[{"id":"A","text":"8辆"},{"id":"B","text":"9辆"},{"id":"C","text":"10辆"},{"id":"D","text":"11辆"}],"answer":"B","explanation":"两种装法的货物总量相等：3500n+5000=4000n+500，解得n=9。"},{"id":98,"topic":"容斥原理","question":"100名村民从甲、乙、丙中选代表。已统计61票：甲35票、乙10票、丙16票。余下选票中甲至少再得多少票就一定当选？","options":[{"id":"A","text":"10票"},{"id":"B","text":"12票"},{"id":"C","text":"11票"},{"id":"D","text":"13票"}],"answer":"C","explanation":"若甲再得x票，最不利时其余39-x票全给当前第二名丙。要保证当选需35+x>16+39-x，解得x>10，所以至少11票。"},{"id":99,"topic":"工程问题","question":"一项工程原计划300天完成。开工100天后，工作效率下降20%。工程比原计划推迟多少天？","options":[{"id":"A","text":"45天"},{"id":"B","text":"55天"},{"id":"C","text":"60天"},{"id":"D","text":"50天"}],"answer":"D","explanation":"前100天完成1/3，剩余原本需200天；效率降为80%后需200÷0.8=250天，因此推迟50天。"},{"id":100,"topic":"几何问题","question":"平面内一个正方形有多少条对称轴？","options":[{"id":"A","text":"4条"},{"id":"B","text":"3条"},{"id":"C","text":"5条"},{"id":"D","text":"6条"}],"answer":"A","explanation":"两条对角线和两组对边中点的连线都是对称轴，共4条。"},{"id":101,"topic":"概率","question":"两个独立报警器在紧急情况下发出信号的概率分别为0.95和0.92。至少一个报警的概率是多少？","options":[{"id":"A","text":"0.896"},{"id":"B","text":"0.996"},{"id":"C","text":"1.096"},{"id":"D","text":"1.196"}],"answer":"B","explanation":"两者都不报警的概率为0.05×0.08=0.004，所以至少一个报警的概率为1-0.004=0.996。"},{"id":102,"topic":"数列规律","question":"找规律：1/2，-1/4，1/6，-1/8，（ ）。","options":[{"id":"A","text":"0/10"},{"id":"B","text":"2/10"},{"id":"C","text":"1/10"},{"id":"D","text":"3/10"}],"answer":"C","explanation":"分母是连续偶数2、4、6、8、10，正负号交替，下一项为1/10。"},{"id":103,"topic":"方程应用","question":"计算：12.5×0.15×16。","options":[{"id":"A","text":"27"},{"id":"B","text":"33"},{"id":"C","text":"36"},{"id":"D","text":"30"}],"answer":"D","explanation":"先算12.5×16=200，再乘0.15，得到30。"},{"id":104,"topic":"几何问题","question":"一个圆与一个三角形的边界最多有多少个交点？","options":[{"id":"A","text":"6个"},{"id":"B","text":"5个"},{"id":"C","text":"7个"},{"id":"D","text":"8个"}],"answer":"A","explanation":"圆与三角形的每条边最多有2个交点，3条边最多有3×2=6个交点。"},{"id":105,"topic":"几何问题","question":"用长度一定的封闭曲线围图形，哪种形状围成的面积最大？","options":[{"id":"A","text":"圆形"},{"id":"B","text":"正方形"},{"id":"C","text":"菱形"},{"id":"D","text":"长方形"}],"answer":"A","explanation":"等周问题的结论是：在周长相同的平面图形中，圆的面积最大。"},{"id":106,"topic":"方程应用","question":"计算0.7的5次方。","options":[{"id":"A","text":"0.06807"},{"id":"B","text":"0.26807"},{"id":"C","text":"0.16807"},{"id":"D","text":"0.36807"}],"answer":"C","explanation":"0.7⁵=7⁵/10⁵=16807/100000=0.16807。"},{"id":107,"topic":"方程应用","question":"比较579/580、1427/1428和42/43的大小。","options":[{"id":"A","text":"1427/1428＞579/580＞42/43"},{"id":"B","text":"579/580＞1427/1428＞42/43"},{"id":"C","text":"42/43＞579/580＞1427/1428"},{"id":"D","text":"579/580＞42/43＞1427/1428"}],"answer":"A","explanation":"三个分数都可写成1减一个单位分数。1/1428最小、1/580次之、1/43最大，所以大小顺序如答案。"},{"id":108,"topic":"行程问题","question":"甲、乙从A地到B地分别需30分钟和40分钟。甲比乙晚出发5分钟，甲出发多少分钟后追上乙？","options":[{"id":"A","text":"10分钟"},{"id":"B","text":"15分钟"},{"id":"C","text":"20分钟"},{"id":"D","text":"25分钟"}],"answer":"B","explanation":"设甲出发t分钟后追上，则乙已走t+5分钟。由t/30=(t+5)/40，解得t=15。"},{"id":109,"topic":"排列组合","question":"制作一面国旗需要3种颜色，制作4面完全相同的国旗需要多少种颜色？","options":[{"id":"A","text":"2种"},{"id":"B","text":"3种"},{"id":"C","text":"4种"},{"id":"D","text":"5种"}],"answer":"B","explanation":"国旗数量增加不改变每面旗的配色种类，仍是3种。"},{"id":110,"topic":"方程应用","question":"小罗、小宋、小王3人轮流下象棋，每局两人参赛，输者下一局休息。若小罗休息2局、小王下8局、小宋下5局，第9局是哪两人比赛？","options":[{"id":"A","text":"小罗和小宋"},{"id":"B","text":"小宋和小王"},{"id":"C","text":"小罗和小王"},{"id":"D","text":"无法确定"}],"answer":"C","explanation":"依据每局输者下一局休息，把各人的参赛与休息次数按局次排列，可锁定第9局参赛者为小罗和小王。"},{"id":111,"topic":"利润经济","question":"某股票6月份下跌20%，6月30日收盘价为每股12元。5月31日收盘价是多少？","options":[{"id":"A","text":"13元"},{"id":"B","text":"17元"},{"id":"C","text":"19元"},{"id":"D","text":"15元"}],"answer":"D","explanation":"下跌后的价格是原价的80%，原价=12÷0.8=15元。"},{"id":112,"topic":"工程问题","question":"甲、乙单独完成同一工程分别需40天、24天。乙先做12天，剩余由甲完成，甲还需多少天？","options":[{"id":"A","text":"20天"},{"id":"B","text":"18天"},{"id":"C","text":"22天"},{"id":"D","text":"24天"}],"answer":"A","explanation":"乙完成一半，剩余一半由甲做，需要40×1/2=20天。"},{"id":113,"topic":"方程应用","question":"一个分数的分子不变，分母扩大到原来的8倍，分数值如何变化？","options":[{"id":"A","text":"扩大到原来的8倍"},{"id":"B","text":"缩小到原来的1/8"},{"id":"C","text":"缩小到原来的1/4"},{"id":"D","text":"大小不变"}],"answer":"B","explanation":"分母扩大8倍相当于整个分数除以8，因此新值是原来的1/8。"},{"id":114,"topic":"方程应用","question":"a是b的2倍，b的3倍减1等于14。a是多少？","options":[{"id":"A","text":"9"},{"id":"B","text":"11"},{"id":"C","text":"10"},{"id":"D","text":"12"}],"answer":"C","explanation":"3b-1=14，得b=5，因此a=2b=10。"},{"id":115,"topic":"方程应用","question":"比较4⁸、5⁷、6⁶、7⁵的大小，哪个最大？","options":[{"id":"A","text":"4⁷"},{"id":"B","text":"6⁷"},{"id":"C","text":"7⁷"},{"id":"D","text":"5⁷"}],"answer":"D","explanation":"计算或拆分比较：4⁸=65536，5⁷=78125，6⁶=46656，7⁵=16807，最大是5⁷。"},{"id":116,"topic":"数列规律","question":"找规律：6，9，（ ），24，39。","options":[{"id":"A","text":"15"},{"id":"B","text":"13"},{"id":"C","text":"17"},{"id":"D","text":"19"}],"answer":"A","explanation":"相邻差依次为3、6、9、15，可看作前两差之和生成后一差；缺项为9+6=15。"},{"id":117,"topic":"方程应用","question":"计算1996+1997+1998+1999+2000。","options":[{"id":"A","text":"8991"},{"id":"B","text":"9990"},{"id":"C","text":"10989"},{"id":"D","text":"11988"}],"answer":"B","explanation":"五个连续整数的平均数是1998，总和为1998×5=9990。"},{"id":118,"topic":"几何问题","question":"边长40米的正方形，将边长增加20米后，面积增加多少平方米？","options":[{"id":"A","text":"1800平方米"},{"id":"B","text":"2200平方米"},{"id":"C","text":"2000平方米"},{"id":"D","text":"2400平方米"}],"answer":"C","explanation":"新面积60²，原面积40²，增加3600-1600=2000平方米。"},{"id":119,"topic":"计数问题","question":"有10瓶啤酒，喝完后每3个空瓶可换1瓶啤酒。最多能喝多少瓶？","options":[{"id":"A","text":"13瓶"},{"id":"B","text":"15瓶"},{"id":"C","text":"16瓶"},{"id":"D","text":"14瓶"}],"answer":"D","explanation":"10个空瓶先换3瓶，剩1个；喝完后有4个空瓶，再换1瓶，最终剩2个空瓶，共喝10+3+1=14瓶。"},{"id":120,"topic":"方程应用","question":"下列哪个分数大于4/5且小于5/6？","options":[{"id":"A","text":"49/60"},{"id":"B","text":"44/60"},{"id":"C","text":"54/60"},{"id":"D","text":"59/60"}],"answer":"A","explanation":"通分得4/5=48/60、5/6=50/60，所以49/60符合。"},{"id":121,"topic":"工程问题","question":"修建水库，甲村单独投资还缺92万元，乙村单独投资还缺88万元，两村合作仍缺20万元。总投资是多少？","options":[{"id":"A","text":"144万元"},{"id":"B","text":"160万元"},{"id":"C","text":"176万元"},{"id":"D","text":"192万元"}],"answer":"B","explanation":"设总投资x万元，(x-92)+(x-88)=x-20，解得x=160。"},{"id":122,"topic":"容斥原理","question":"从3、5、7、11这4个质数中至少选1个相乘，可以得到多少个不同的积？","options":[{"id":"A","text":"13个"},{"id":"B","text":"17个"},{"id":"C","text":"15个"},{"id":"D","text":"19个"}],"answer":"C","explanation":"不同质数的乘积能唯一对应所选质数集合，因此不同积的数量等于4个元素的非空子集数2⁴-1=15。"},{"id":123,"topic":"方程应用","question":"甲、乙两数之和为456，甲的末位是5，去掉末位5后所得数等于乙。甲是多少？","options":[{"id":"A","text":"373"},{"id":"B","text":"457"},{"id":"C","text":"499"},{"id":"D","text":"415"}],"answer":"D","explanation":"设乙为x，则甲为10x+5。由10x+5+x=456，得x=41，所以甲为415。"},{"id":124,"topic":"方程应用","question":"计算1+2+3+…+999。","options":[{"id":"A","text":"499500"},{"id":"B","text":"449550"},{"id":"C","text":"549450"},{"id":"D","text":"599400"}],"answer":"A","explanation":"等差数列求和：(1+999)×999÷2=499500。"},{"id":125,"topic":"排列组合","question":"从6个不同颜色的球中依次取出2个且不放回，有多少种不同取法？","options":[{"id":"A","text":"27种"},{"id":"B","text":"30种"},{"id":"C","text":"33种"},{"id":"D","text":"36种"}],"answer":"B","explanation":"第一次有6种选择，第二次有5种，按顺序共有6×5=30种。"},{"id":126,"topic":"数列规律","question":"找规律：1，8，9，（ ），25。","options":[{"id":"A","text":"58"},{"id":"B","text":"70"},{"id":"C","text":"64"},{"id":"D","text":"76"}],"answer":"C","explanation":"奇数位置是1²、3²、5²，偶数位置是2³、4³，所以缺项为4³=64。"},{"id":127,"topic":"利润经济","question":"用2万元购买甲、乙股票，投资额之比4∶1。甲每股8元、乙每股4元；卖出时分别为10元、3元。共获利多少元？","options":[{"id":"A","text":"2700元"},{"id":"B","text":"3300元"},{"id":"C","text":"3600元"},{"id":"D","text":"3000元"}],"answer":"D","explanation":"甲投入16000元买2000股，获利4000元；乙投入4000元买1000股，亏损1000元，净获利3000元。"},{"id":128,"topic":"方程应用","question":"木蛙在井底向上爬井深10米青蛙每次跳上5米又滑下来4米象这样青蛙需跳凡次方可出井?","options":[{"id":"A","text":"6K"},{"id":"B","text":"9M dD. 10K"},{"id":"C","text":"以上都不正确"},{"id":"D","text":"以上都不正确"}],"answer":"A","explanation":"本题考查方程应用。设未知数，把题干中的等量关系翻译成方程并求解。计算结果为“6K”，因此选择A。"},{"id":129,"topic":"利润经济","question":"若某股票的一年前的价格为10元一年中的税后股息为025现在的市价为12元。 在不考虑交易费用的情况下一年内该股票的收益率为 ()。 hA. 20%W","options":[{"id":"A","text":"7"},{"id":"B","text":"8"},{"id":"C","text":"9"},{"id":"D","text":"10"}],"answer":"B","explanation":"本题考查利润经济。分别写出成本、售价、数量与利润之间的关系，再比较或求极值。计算结果为“8”，因此选择B。"},{"id":130,"topic":"方程应用","question":"两个正数的等差中项为15，等比中项为12。两数之差的绝对值是多少？","options":[{"id":"A","text":"16"},{"id":"B","text":"20"},{"id":"C","text":"18"},{"id":"D","text":"22"}],"answer":"C","explanation":"设两数x、y，则x+y=30、xy=144。(x-y)²=(x+y)²-4xy=900-576=324，所以差为18。"},{"id":131,"topic":"方程应用","question":"共有200人具中有50火买","options":[{"id":"A","text":"产品40人"},{"id":"B","text":"产品75人"},{"id":"C","text":"产品60人"},{"id":"D","text":"产品85人产品已知15人既买了"}],"answer":"A","explanation":"本题考查方程应用。设未知数，把题干中的等量关系翻译成方程并求解。计算结果为“产品40人”，因此选择A。"},{"id":132,"topic":"年龄问题","question":"10年前父亲年龄是女儿的7倍，15年后父亲年龄是女儿的2倍。女儿现在多少岁？","options":[{"id":"A","text":"15岁"},{"id":"B","text":"13岁"},{"id":"C","text":"17岁"},{"id":"D","text":"19岁"}],"answer":"A","explanation":"设父亲、女儿现在F、D岁。F-10=7(D-10)，F+15=2(D+15)，联立解得D=15。"},{"id":133,"topic":"容斥原理","question":"某出版社新招10名英文、法文、日文编辑。只有小李同时会英文和日文，其余每人只会一种。会法文的比会英文的多4人，且是会日文人数的2倍。只会英文的有几人？","options":[{"id":"A","text":"0人"},{"id":"B","text":"1人"},{"id":"C","text":"2人"},{"id":"D","text":"3人"}],"answer":"B","explanation":"设会英文、法文、日文人数为E、F、J。因小李被重复计算一次，E+F+J=11；又F=E+4=2J。解得E=2、F=6、J=3，只会英文的为E-1=1人。"},{"id":134,"topic":"计数问题","question":"某城市9月平均气温为28.5℃，且最热日与最冷日的平均气温相差不超过10℃。平均气温不低于30℃的日子最多有多少天？","options":[{"id":"A","text":"23天"},{"id":"B","text":"27天"},{"id":"C","text":"25天"},{"id":"D","text":"29天"}],"answer":"C","explanation":"要让高温天数尽量多，可令高温日为30℃、其余日为20℃。由(30n+20(30-n))/30≤28.5得n≤25.5，因此最多25天。"},{"id":135,"topic":"方程应用","question":"甲、乙、丙进行1000米赛跑。甲到终点时乙还差100米，丙比乙再落后90米。若甲比乙早到18秒，乙比丙早到多少秒？","options":[{"id":"A","text":"18秒"},{"id":"B","text":"22秒"},{"id":"C","text":"24秒"},{"id":"D","text":"20秒"}],"answer":"D","explanation":"甲到终点时，乙、丙分别跑900米、810米，速度比为1∶0.9∶0.81。由甲比乙早18秒可得甲用时162秒、乙180秒、丙200秒，乙比丙早20秒。"},{"id":136,"topic":"数列规律","question":"找规律：0，7，26，63，（ ）。","options":[{"id":"A","text":"124"},{"id":"B","text":"112"},{"id":"C","text":"136"},{"id":"D","text":"148"}],"answer":"A","explanation":"各项依次为1³-1、2³-1、3³-1、4³-1，下一项为5³-1=124。"},{"id":137,"topic":"方程应用","question":"计算：25×44+99-110。","options":[{"id":"A","text":"980"},{"id":"B","text":"1089"},{"id":"C","text":"1198"},{"id":"D","text":"1307"}],"answer":"B","explanation":"25×44=1100，1100+99-110=1089。"},{"id":138,"topic":"数论问题","question":"树上有8只鸟，猎人开枪打中2只，其余鸟都飞走了。树上还剩几只活鸟？","options":[{"id":"A","text":"-1只"},{"id":"B","text":"1只"},{"id":"C","text":"0只"},{"id":"D","text":"2只"}],"answer":"C","explanation":"枪响后没有被打中的鸟会飞走，因此树上不剩活鸟。"},{"id":139,"topic":"方程应用","question":"求199、202、207、192、200的平均数。","options":[{"id":"A","text":"180"},{"id":"B","text":"220"},{"id":"C","text":"240"},{"id":"D","text":"200"}],"answer":"D","explanation":"五个数的和为1000，平均数为1000÷5=200。"},{"id":140,"topic":"容斥原理","question":"某校100人，60人参加外语社团，72人参加计算机社团，其中8人只参加外语社团。只参加计算机社团的有多少人？","options":[{"id":"A","text":"20人"},{"id":"B","text":"18人"},{"id":"C","text":"22人"},{"id":"D","text":"24人"}],"answer":"A","explanation":"两社团都参加的有60-8=52人，只参加计算机的有72-52=20人。"},{"id":141,"topic":"几何问题","question":"一个长方形分成9个小长方形，左上、左下、右上角面积分别为8、12、18。右下角面积是多少？","options":[{"id":"A","text":"24"},{"id":"B","text":"27"},{"id":"C","text":"30"},{"id":"D","text":"33"}],"answer":"B","explanation":"四角面积满足左上×右下=左下×右上，因此右下=12×18÷8=27。"},{"id":142,"topic":"数论问题","question":"最小的正整数中，除以11余10，除以13余8的是多少？","options":[{"id":"A","text":"19"},{"id":"B","text":"23"},{"id":"C","text":"21"},{"id":"D","text":"25"}],"answer":"C","explanation":"21÷11余10，21÷13余8，且它是满足条件的最小正整数。"},{"id":143,"topic":"方程应用","question":"计算：(2/3-1/2)÷(11/24)。","options":[{"id":"A","text":"3/11"},{"id":"B","text":"5/11"},{"id":"C","text":"6/11"},{"id":"D","text":"4/11"}],"answer":"D","explanation":"括号内为1/6，再除以11/24等于1/6×24/11=4/11。"},{"id":144,"topic":"方程应用","question":"某工厂男工人数是女工人数的1/3，女工比男工多380人。全厂共有多少人？","options":[{"id":"A","text":"760人"},{"id":"B","text":"684人"},{"id":"C","text":"836人"},{"id":"D","text":"912人"}],"answer":"A","explanation":"设男工x人、女工3x人，则3x-x=380，x=190，总人数4x=760。"},{"id":145,"topic":"方程应用","question":"出租车10公里内收费10.4元, 每走1公里1.6元,20公里收炭多少元?","options":[{"id":"A","text":"26"},{"id":"B","text":"20"},{"id":"C","text":"20.°8"},{"id":"D","text":"26.4 sh"}],"answer":"D","explanation":"本题考查方程应用。设未知数，把题干中的等量关系翻译成方程并求解。计算结果为“26.4 sh”，因此选择D。"},{"id":146,"topic":"方程应用","question":"计算：1/(12×13)+1/(13×14)+…+1/(19×20)。","options":[{"id":"A","text":"0/30"},{"id":"B","text":"2/30"},{"id":"C","text":"1/30"},{"id":"D","text":"3/30"}],"answer":"C","explanation":"利用1/[n(n+1)]=1/n-1/(n+1)，各项相消后只剩1/12-1/20=1/30。"},{"id":147,"topic":"方程应用","question":"一共100道选挂题 》 对一道1分,、 错一道0.5分, 得分:91分, 共错几道 (Ad","options":[{"id":"B","text":"5"},{"id":"C","text":"6"},{"id":"D","text":"7 S"}],"answer":"C","explanation":"本题考查方程应用。设未知数，把题干中的等量关系翻译成方程并求解。计算结果为“6”，因此选择C。"},{"id":148,"topic":"方程应用","question":"用绳子测井深：三折后长出井口4米，四折后长出井口1米。井深多少米？","options":[{"id":"A","text":"8米"},{"id":"B","text":"7米"},{"id":"C","text":"9米"},{"id":"D","text":"10米"}],"answer":"A","explanation":"绳长满足3(d+4)=4(d+1)，解得井深d=8米。"},{"id":149,"topic":"几何问题","question":"一个圆与一个三角形的边界最多有多少个交点？","options":[{"id":"A","text":"5个"},{"id":"B","text":"6个"},{"id":"C","text":"7个"},{"id":"D","text":"8个"}],"answer":"B","explanation":"每条边与圆最多有2个交点，三条边最多6个。"},{"id":150,"topic":"年龄问题","question":"哥哥和弟弟今年年龄和55岁。曾有一年，哥哥当时年龄等于弟弟今年年龄，且是弟弟当时年龄的2倍。哥哥今年多少岁？","options":[{"id":"A","text":"30岁"},{"id":"B","text":"36岁"},{"id":"C","text":"33岁"},{"id":"D","text":"39岁"}],"answer":"C","explanation":"设哥哥x岁，按年龄差建立方程55-x=2(110-3x)，解得x=33。"},{"id":151,"topic":"比例百分数","question":"小王参加了五门百分制的测验, 每门成绩都是敷数, 典中语文94分, 数学的得分最商, 外语的得分等于语文和物理的平均分, 物理的得分等于五门的平均分, 化学的得分比外语多2分, 并且是五门中第二高的得分, 问小王的物理考了多少分?","options":[{"id":"A","text":"94"},{"id":"B","text":"95"},{"id":"C","text":"96"},{"id":"D","text":"97"}],"answer":"C","explanation":"本题考查比例百分数。把基准量设为1份或100%，按对应比例换算。计算结果为“96”，因此选择C。"},{"id":152,"topic":"数论问题","question":"某单位四个兴趣组中，羽毛球人数是乒乓球的2倍，足球人数是篮球的3倍，乒乓球人数的4倍等于其余三组人数之和。羽毛球人数等于什么？","options":[{"id":"A","text":"足球组的1.5倍"},{"id":"B","text":"篮球组的3倍"},{"id":"C","text":"足球组与篮球组人数之和"},{"id":"D","text":"乒乓球组与足球组人数之和"}],"answer":"C","explanation":"设乒乓球p、篮球b，则羽毛球2p、足球3b。由4p=2p+b+3b得p=2b，所以羽毛球4b，恰等于足球3b与篮球b之和。"},{"id":153,"topic":"方程应用","question":"一个班排队：3人一排比2人一排少9排，4人一排比3人一排少5排。若5人一排，共有多少排？","options":[{"id":"A","text":"10排"},{"id":"B","text":"11排"},{"id":"C","text":"12排"},{"id":"D","text":"13排"}],"answer":"B","explanation":"55人时，2人一排需28排、3人一排需19排，相差9排；4人一排14排，再少5排；5人一排正好11排。"},{"id":154,"topic":"利润经济","question":"用2万元按4∶1购买甲、乙股票，甲每股8元、乙每股4元。后来分别以10元、3元卖出，共获利多少？","options":[{"id":"A","text":"2700元"},{"id":"B","text":"3300元"},{"id":"C","text":"3000元"},{"id":"D","text":"3600元"}],"answer":"C","explanation":"甲获利2000×2=4000元，乙亏损1000×1=1000元，净获利3000元。"},{"id":155,"topic":"排列组合","question":"黄、白、蓝三个球从左到右排列，有多少种不同排法？","options":[{"id":"A","text":"5种"},{"id":"B","text":"7种"},{"id":"C","text":"8种"},{"id":"D","text":"6种"}],"answer":"D","explanation":"三个不同元素全排列共有3!=6种。"},{"id":156,"topic":"几何问题","question":"一个边长2米的正方体上叠放一个边长1米的正方体，底面和接触面不粉刷。需要粉刷的外表面积是多少？","options":[{"id":"A","text":"24平方米"},{"id":"B","text":"22平方米"},{"id":"C","text":"26平方米"},{"id":"D","text":"28平方米"}],"answer":"A","explanation":"大正方体外露面积为16+3=19平方米，小正方体外露5个面共5平方米，总计24平方米。"},{"id":157,"topic":"数论问题","question":"求1～100中所有能被5整除的数之和。","options":[{"id":"A","text":"945"},{"id":"B","text":"1050"},{"id":"C","text":"1155"},{"id":"D","text":"1260"}],"answer":"B","explanation":"这些数是5、10、…、100，共20项，和为(5+100)×20÷2=1050。"},{"id":158,"topic":"行程问题","question":"小张、小王同时从A地骑摩托车去B地，速度分别为40千米/时、48千米/时。小王到B地后立即返回，15分钟后与小张相遇。AB相距多少千米？","options":[{"id":"A","text":"119千米"},{"id":"B","text":"145千米"},{"id":"C","text":"132千米"},{"id":"D","text":"158千米"}],"answer":"C","explanation":"相遇时小王已返程12千米，小张距B地也为12千米，两人路程差24千米。速度差8千米/时，所以已行3小时；AB距离为48×3-12=132千米。"},{"id":159,"topic":"方程应用","question":"两仁水桶共盛40斤水, 如果把第一桶里的8斤水倒入第二个水桶里, 两个水梓里的水就一样多, 第二桶水重多少斤?() ai","options":[{"id":"A","text":"21"},{"id":"B","text":"18"},{"id":"C","text":"12"},{"id":"D","text":"10"}],"answer":"C","explanation":"本题考查方程应用。设未知数，把题干中的等量关系翻译成方程并求解。计算结果为“12”，因此选择C。"},{"id":160,"topic":"数论问题","question":"一根绳子先剪去2米，再剪去剩余的一半，最后还剩5米。原长多少米？","options":[{"id":"A","text":"12米"},{"id":"B","text":"11米"},{"id":"C","text":"13米"},{"id":"D","text":"14米"}],"answer":"A","explanation":"第二次剪之前有10米，第一次剪之前有10+2=12米。"},{"id":161,"topic":"方程应用","question":"一桶油连桶重100千克，倒去一半油后连桶重45千克。下列判断正确的是？","options":[{"id":"A","text":"桶重10千克"},{"id":"B","text":"桶重20千克"},{"id":"C","text":"桶重45千克"},{"id":"D","text":"题目条件矛盾"}],"answer":"D","explanation":"设油重x、桶重y，则x+y=100、x/2+y=45，相减得x=110、y=-10。桶重不可能为负数，因此原数据不合理。"},{"id":162,"topic":"数论问题","question":"一本100多页的书被撕掉4张纸（共8个页码），剩余页码总和为8037。这本书最多有多少页？","options":[{"id":"A","text":"121页"},{"id":"B","text":"147页"},{"id":"C","text":"134页"},{"id":"D","text":"160页"}],"answer":"C","explanation":"计算前n个页码总和，并检查被撕去的4张纸所对应的8个页码。n=134时总和9045，与8037相差1008，可由4张纸的页码组成；再增页数则不满足。"},{"id":163,"topic":"概率","question":"从长度为1、2、3、4、5、6的6根小棒中任取3根，能组成三角形的概率是多少？","options":[{"id":"A","text":"6/20"},{"id":"B","text":"8/20"},{"id":"C","text":"9/20"},{"id":"D","text":"7/20"}],"answer":"D","explanation":"总取法C(6,3)=20。逐组检验两短边之和大于最长边，符合的有7组，概率7/20。"},{"id":164,"topic":"数列规律","question":"找规律：1，-1/2，1/3，-1/4，1/5，（ ）。","options":[{"id":"A","text":"-1/6"},{"id":"B","text":"-2/6"},{"id":"C","text":"0/6"},{"id":"D","text":"1/6"}],"answer":"A","explanation":"分母依次加1，正负号交替，所以下一项为-1/6。"},{"id":165,"topic":"方程应用","question":"从10:15到16:45经过了多长时间？","options":[{"id":"A","text":"5小时30分钟"},{"id":"B","text":"6小时30分钟"},{"id":"C","text":"7小时30分钟"},{"id":"D","text":"8小时30分钟"}],"answer":"B","explanation":"10:15到16:15是6小时，再到16:45是30分钟。"},{"id":166,"topic":"方程应用","question":"分数1/3的分子不变，分母扩大到原来的3倍，分数值如何变化？","options":[{"id":"A","text":"扩大到原来的3倍"},{"id":"B","text":"缩小到原来的1/3"},{"id":"C","text":"缩小到原来的1/9"},{"id":"D","text":"大小不变"}],"answer":"B","explanation":"新分数为1/9，而(1/9)÷(1/3)=1/3。"},{"id":167,"topic":"排列组合","question":"48支足球队平均分成8组，每组内单循环赛。初赛共比赛多少场？","options":[{"id":"A","text":"108场"},{"id":"B","text":"132场"},{"id":"C","text":"144场"},{"id":"D","text":"120场"}],"answer":"D","explanation":"每组6队，单循环有C(6,2)=15场，8组共15×8=120场。"},{"id":168,"topic":"方程应用","question":"375, 127,248,121, ¢)","options":[{"id":"A","text":"369"},{"id":"B","text":"127"},{"id":"C","text":"127: 颂 -369"},{"id":"D","text":"以上都不正确"}],"answer":"A","explanation":"本题考查方程应用。设未知数，把题干中的等量关系翻译成方程并求解。计算结果为“369”，因此选择A。"},{"id":169,"topic":"数列规律","question":"找规律：10，17，（ ），37。","options":[{"id":"A","text":"23"},{"id":"B","text":"26"},{"id":"C","text":"29"},{"id":"D","text":"32"}],"answer":"B","explanation":"相邻增量依次为7、9、11，所以缺项为17+9=26。"},{"id":170,"topic":"利润经济","question":"将进货单价为80元的商品拯90元售出时, 能卖出400个, 已知这种商品每涨价1元, 共销售量就要减少20个, 为了获得最大利涧, 每个售价应定为","options":[{"id":"A","text":"95"},{"id":"B","text":"100"},{"id":"C","text":"105"},{"id":"D","text":"110"}],"answer":"A","explanation":"本题考查利润经济。分别写出成本、售价、数量与利润之间的关系，再比较或求极值。计算结果为“95”，因此选择A。"},{"id":171,"topic":"排列组合","question":"现有1分、2分、5分、1角、5角、1元硬币各1枚，至少使用1枚，可组成多少种不同币值？","options":[{"id":"A","text":"57种"},{"id":"B","text":"69种"},{"id":"C","text":"75种"},{"id":"D","text":"63种"}],"answer":"D","explanation":"各面值均大于之前所有小面值之和，因此不同子集的币值不同。6枚硬币的非空子集数为2⁶-1=63。"},{"id":172,"topic":"方程应用","question":"中午12点时针与分针重合，到下一个中午12点之前，两针共重合多少次？","options":[{"id":"A","text":"11次"},{"id":"B","text":"10次"},{"id":"C","text":"12次"},{"id":"D","text":"13次"}],"answer":"A","explanation":"分针相对时针每12/11小时追上一圈，因此12小时内重合11次。"},{"id":173,"topic":"计数问题","question":"有10个空酒瓶，每3个空瓶可换1瓶酒；允许最后借1个空瓶并在喝完后归还。最多能喝几瓶？","options":[{"id":"A","text":"4瓶"},{"id":"B","text":"5瓶"},{"id":"C","text":"6瓶"},{"id":"D","text":"7瓶"}],"answer":"B","explanation":"10个空瓶换3瓶，喝完后有4个；再换1瓶后剩2个，借1个换1瓶，喝完归还借来的空瓶，共5瓶。"},{"id":174,"topic":"方程应用","question":"32, 27, 23, 20, eX","options":[{"id":"A","text":"4"},{"id":"B","text":"6"},{"id":"C","text":"5"},{"id":"D","text":"7"}],"answer":"C","explanation":"本题考查方程应用。设未知数，把题干中的等量关系翻译成方程并求解。计算结果为“5”，因此选择C。"},{"id":175,"topic":"方程应用","question":"某校1000人，男女比6∶4，教师与学生比2∶8。若男教师100人，女学生有多少人？","options":[{"id":"A","text":"270人"},{"id":"B","text":"330人"},{"id":"C","text":"360人"},{"id":"D","text":"300人"}],"answer":"D","explanation":"全校女性400人，教师200人。男教师100人，则女教师100人，女学生400-100=300人。"},{"id":176,"topic":"几何问题","question":"宽为2a的长方形铁片，两边各向上折起x形成矩形水槽。x为何值时截面积最大？","options":[{"id":"A","text":"a/4"},{"id":"B","text":"a/3"},{"id":"C","text":"a/2"},{"id":"D","text":"2a/3"}],"answer":"C","explanation":"截面积x(2a-2x)是开口向下的二次函数，顶点在x=a/2。"},{"id":177,"topic":"方程应用","question":"23支队伍参加单淘汰赛，每轮两两比赛，队伍数为奇数时有1队轮空。整个赛事共出现几次轮空？","options":[{"id":"A","text":"1次"},{"id":"B","text":"2次"},{"id":"C","text":"3次"},{"id":"D","text":"4次"}],"answer":"B","explanation":"23队首轮有1次轮空，晋级后12队；12→6→3，3队这一轮再有1次轮空，之后2→1，共2次。"},{"id":178,"topic":"方程应用","question":"33÷70所得小数的小数点后第1000位数字是多少？","options":[{"id":"A","text":"3"},{"id":"B","text":"5"},{"id":"C","text":"4"},{"id":"D","text":"6"}],"answer":"C","explanation":"33/70=0.4(714285)循环。除去首位4后，循环节长6；第1000位对应循环节第3位，数字为4。"},{"id":179,"topic":"方程应用","question":"求199、202、207、192、200的平均数。","options":[{"id":"A","text":"180"},{"id":"B","text":"220"},{"id":"C","text":"240"},{"id":"D","text":"200"}],"answer":"D","explanation":"五个数的和是1000，平均数为1000÷5=200。"},{"id":180,"topic":"计数问题","question":"晴天浇水量是阴天的2.5倍。满箱水若天天晴可用18天；6月30天晴阴相间后恰好用完。6月有多少个阴天？","options":[{"id":"A","text":"20天"},{"id":"B","text":"18天"},{"id":"C","text":"22天"},{"id":"D","text":"24天"}],"answer":"A","explanation":"以阴天用水量为1，水箱容量为18×2.5=45。设阴天x天，则x+2.5(30-x)=45，解得x=20。"},{"id":181,"topic":"工程问题","question":"甲村单独修坝缺92万元，乙村单独修缺88万元，两村合作仍缺20万元。修坝需多少万元？","options":[{"id":"A","text":"144万元"},{"id":"B","text":"160万元"},{"id":"C","text":"176万元"},{"id":"D","text":"192万元"}],"answer":"B","explanation":"设总额x，列式(x-92)+(x-88)=x-20，解得x=160。"},{"id":182,"topic":"方程应用","question":"最小的两位数、三位数和四位数相加，结果是多少？","options":[{"id":"A","text":"999"},{"id":"B","text":"1221"},{"id":"C","text":"1110"},{"id":"D","text":"1332"}],"answer":"C","explanation":"10+100+1000=1110。"},{"id":183,"topic":"方程应用","question":"题目规定纽约时间比香港时间快13小时。香港6月1日20:00打电话，纽约是几点？","options":[{"id":"A","text":"5月2日9:00"},{"id":"B","text":"7月2日9:00"},{"id":"C","text":"8月2日9:00"},{"id":"D","text":"6月2日9:00"}],"answer":"D","explanation":"按题目给定时差，纽约时间为香港时间加13小时，即次日9:00。"},{"id":184,"topic":"方程应用","question":"翻日历,: 翎了7张, 和加起来77, 问这一天是几号? al4号、","options":[{"id":"B","text":"1l3号"},{"id":"C","text":"15号、 dl17号"}],"answer":"C","explanation":"本题考查方程应用。设未知数，把题干中的等量关系翻译成方程并求解。计算结果为“15号、 dl17号”，因此选择C。"},{"id":185,"topic":"计数问题","question":"在公路一侧植树。每隔3米种1棵会多3棵树，每隔2.5米种1棵会缺37棵树，两端都种。公路长多少米？","options":[{"id":"A","text":"540米"},{"id":"B","text":"600米"},{"id":"C","text":"660米"},{"id":"D","text":"720米"}],"answer":"B","explanation":"设路长L、现有树N，则N=L/3+1+3=L/2.5+1-37。解得L=600米。"},{"id":186,"topic":"数论问题","question":"一本100多页的书被撕掉4张纸，剩余页码数字之和为8037。这本书最多有多少页？","options":[{"id":"A","text":"121页"},{"id":"B","text":"147页"},{"id":"C","text":"134页"},{"id":"D","text":"160页"}],"answer":"C","explanation":"逐一检查100多页时的页码总和与4张纸对应的8个页码。134页的总和为9045，减去相应8个页码后可得8037，再增加页数则不能满足。"},{"id":187,"topic":"方程应用","question":"公司招人35人, 只能胜任","options":[{"id":"A","text":"的比兼职胜任多1人, 问只胜任"},{"id":"B","text":"江作的人是"},{"id":"C","text":"的两倍, 只能胜任"},{"id":"D","text":"以上都不正确"}],"answer":"B","explanation":"本题考查方程应用。设未知数，把题干中的等量关系翻译成方程并求解。计算结果为“江作的人是”，因此选择B。"},{"id":188,"topic":"数论问题","question":"一个正整数除以11余8，除以13余10，除以17余14。最小值是多少？","options":[{"id":"A","text":"2428"},{"id":"B","text":"2185"},{"id":"C","text":"2671"},{"id":"D","text":"2914"}],"answer":"A","explanation":"三个余数分别比除数小3，所以该数加3同时被11、13、17整除。最小值为11×13×17-3=2428。"},{"id":189,"topic":"排列组合","question":"用1、2、3、4组成无重复数字的四位数，按从小到大排列，第18个是多少？","options":[{"id":"A","text":"3079"},{"id":"B","text":"3421"},{"id":"C","text":"3763"},{"id":"D","text":"4105"}],"answer":"B","explanation":"每个千位数字对应6个数。第18个是千位为3的第6个，后三位1、2、4按升序排列的第6个为421，所以是3421。"},{"id":190,"topic":"方程应用","question":"下列哪个乘积最大？","options":[{"id":"A","text":"599×601"},{"id":"B","text":"598×602"},{"id":"C","text":"590×610"},{"id":"D","text":"500×700"}],"answer":"A","explanation":"都围绕600比较：599×601=600²-1，598×602=600²-4，590×610=600²-100，第一项最大。"},{"id":191,"topic":"方程应用","question":"三个自然数两两相加得8、11、13，两两相乘得15、24、40。三个数的乘积是多少？","options":[{"id":"A","text":"108"},{"id":"B","text":"132"},{"id":"C","text":"144"},{"id":"D","text":"120"}],"answer":"D","explanation":"三个数是3、5、8，乘积为3×5×8=120。"},{"id":192,"topic":"几何问题","question":"用28米围栏围成三角形，第一边长m米，第二边长m+4米，第三边长24-2m米。若第一边是唯一最短边，且第三边长于第二边，m可取哪个整数？","options":[{"id":"A","text":"6"},{"id":"B","text":"5"},{"id":"C","text":"7"},{"id":"D","text":"8"}],"answer":"A","explanation":"三角形条件给m>5，第三边长于第二边给24-2m>m+4，即m<20/3。整数m只能取6。"},{"id":193,"topic":"排列组合","question":"5支足球队单循环赛，胜3分、平各1分、负0分。总积分25分，冠军4战全胜得12分。亚军得多少分？","options":[{"id":"A","text":"4分"},{"id":"B","text":"5分"},{"id":"C","text":"6分"},{"id":"D","text":"7分"}],"answer":"B","explanation":"10场比赛若全分胜负总分30分，实际25分说明有5场平局。冠军4场全胜，剩余4队的6场中5平1胜负，最高者得5分。"},{"id":194,"topic":"容斥原理","question":"按题设，体力、情绪、智力分别以22、28、33天为周期，前半周期为高潮。按每年365天计算，生日时三者首次同时处于高潮的最小年龄是？","options":[{"id":"A","text":"1周岁"},{"id":"B","text":"3周岁"},{"id":"C","text":"2周岁"},{"id":"D","text":"4周岁"}],"answer":"C","explanation":"1周岁时365 mod 22=13，体力不在前半周期；2周岁730天，对22、28、33的余数分别为4、2、4，均在前半周期。"},{"id":195,"topic":"工程问题","question":"电动公交车相较柴油公交车的综合减排效率约为88%。某公交公司通过更换电动车使总体碳排放降低约59%，电动公交车占比约为多少？","options":[{"id":"A","text":"60%"},{"id":"B","text":"74%"},{"id":"C","text":"81%"},{"id":"D","text":"67%"}],"answer":"D","explanation":"若电动车占比为x，则总体减排约为88%x。由0.88x≈0.59，得x≈0.67，即约67%。"},{"id":196,"topic":"行程问题","question":"飞机原计划每分钟飞12千米，后提高到每分钟15千米，比原计划提前30分钟到达。机场到灾区多远？","options":[{"id":"A","text":"1800千米"},{"id":"B","text":"1620千米"},{"id":"C","text":"1980千米"},{"id":"D","text":"2160千米"}],"answer":"A","explanation":"设距离d，d/12-d/15=30，解得d=1800千米。"},{"id":197,"topic":"方程应用","question":"用1、 2、3、4、5组成一个无重复数字的五位数, 组成数字是","options":[{"id":"A","text":"484% 3"},{"id":"B","text":"364%"},{"id":"C","text":"偶数有几种惊况? 明人 es"},{"id":"D","text":"以上都不正确"}],"answer":"A","explanation":"本题考查方程应用。设未知数，把题干中的等量关系翻译成方程并求解。计算结果为“484% 3”，因此选择A。"},{"id":198,"topic":"容斥原理","question":"学校开设语文、数学、美术3种课外班，每名学生至多参加2种，也可以不参加。至少有多少名学生，才能保证有5名学生参加课外班的情况完全相同？","options":[{"id":"A","text":"26人"},{"id":"B","text":"32人"},{"id":"C","text":"29人"},{"id":"D","text":"35人"}],"answer":"C","explanation":"参加方式有：不参加1种、只参加一种3种、参加两种3种，共7种。每种最多4人时有28人，再来1人必有一种方式达到5人，所以至少29人。"},{"id":199,"topic":"比例百分数","question":"某学校目前学生与教师人数之比为30:1。若学生增加50人、教师增加5人，两者之比变为25:1。目前教师有多少人？","options":[{"id":"A","text":"8"},{"id":"B","text":"10"},{"id":"C","text":"12"},{"id":"D","text":"15"}],"answer":"D","explanation":"设目前教师有x人，则(30x+50)/(x+5)=25，解得x=15。"},{"id":200,"topic":"数论问题","question":"小丽读一本书，第一天读全书的4/7，第二天读余下的3/5，还剩84页。全书多少页？","options":[{"id":"A","text":"490页"},{"id":"B","text":"441页"},{"id":"C","text":"539页"},{"id":"D","text":"588页"}],"answer":"A","explanation":"最后剩全书的(1-4/7)(1-3/5)=6/35，所以全书84÷(6/35)=490页。"},{"id":201,"topic":"几何问题","question":"正八面体有多少条棱？","options":[{"id":"A","text":"11条"},{"id":"B","text":"12条"},{"id":"C","text":"13条"},{"id":"D","text":"14条"}],"answer":"B","explanation":"正八面体有8个三角形面，每个面3条边，每条棱被2个面共有，所以棱数8×3÷2=12。"},{"id":202,"topic":"排列组合","question":"1分、2分、5分、1角、2角和1元硬币各1枚，至少取1枚，可组成多少种不同币值？","options":[{"id":"A","text":"57种"},{"id":"B","text":"69种"},{"id":"C","text":"63种"},{"id":"D","text":"75种"}],"answer":"C","explanation":"这些面值使不同非空子集对应不同总金额。6枚硬币有2⁶-1=63个非空子集。"},{"id":203,"topic":"方程应用","question":"前9次测试平均分为17分，第10次测试后，10次平均分为18分。第10次得多少分？","options":[{"id":"A","text":"24分"},{"id":"B","text":"30分"},{"id":"C","text":"33分"},{"id":"D","text":"27分"}],"answer":"D","explanation":"前9次总分9×17=153，10次总分10×18=180，第10次得180-153=27分。"},{"id":204,"topic":"方程应用","question":"计算：12.5×0.15×16÷10。","options":[{"id":"A","text":"3"},{"id":"B","text":"2"},{"id":"C","text":"4"},{"id":"D","text":"5"}],"answer":"A","explanation":"先算12.5×16=200，再算200×0.15÷10=30÷10=3。"},{"id":205,"topic":"方程应用","question":"计算84.78+59.50+66.50+12.43+121.61。","options":[{"id":"A","text":"310.338"},{"id":"B","text":"344.82"},{"id":"C","text":"379.302"},{"id":"D","text":"413.784"}],"answer":"B","explanation":"依次相加得到144.28、210.78、223.21，最后加121.61得344.82。"},{"id":206,"topic":"概率","question":"射击运动员每次射击命中10环的概率是80%,5次射击有4次命中10环的概率是 ()","options":[{"id":"A","text":"80%"},{"id":"B","text":"63.22%"},{"id":"C","text":"40, 96%"},{"id":"D","text":"32.81%"}],"answer":"C","explanation":"本题考查概率。先确定所有等可能结果，再统计满足条件的结果数，用“符合数÷总数”计算。计算结果为“40, 96%”，因此选择C。"},{"id":207,"topic":"年龄问题","question":"赵先生年龄是钱先生的2倍，钱先生比孙先生小7岁。三人年龄和是小于70的素数，且该素数各位数字和为13。三人年龄分别是多少？","options":[{"id":"A","text":"27岁、15岁、22岁"},{"id":"B","text":"33岁、15岁、22岁"},{"id":"C","text":"36岁、15岁、22岁"},{"id":"D","text":"30岁、15岁、22岁"}],"answer":"D","explanation":"逐项检验：30=2×15，15比22小7；三人年龄和67是小于70的素数，且6+7=13，完全符合。"},{"id":208,"topic":"工程问题","question":"甲乙两个工程队合作挖一条隔道, 如果甲队单独施工要20天完成,.. 乙队单独施工要10天完成。 如果甲先挖一天, 然后乙拳替甲挖一天, 再由甲接替乙挖一天 …... 两人如此交替合作。 那么, 挖完这条隧道共要多少天?","options":[{"id":"A","text":"13"},{"id":"B","text":"13.5"},{"id":"C","text":"14"},{"id":"D","text":"15.5"}],"answer":"B","explanation":"本题考查工程问题。把总工作量设为1，将各自效率写成每天完成量后列式。计算结果为“13.5”，因此选择B。"},{"id":209,"topic":"方程应用","question":"4⁸、5⁷、6⁶、7⁵中哪个最大？","options":[{"id":"A","text":"4⁷"},{"id":"B","text":"5⁷"},{"id":"C","text":"6⁷"},{"id":"D","text":"7⁷"}],"answer":"B","explanation":"分别为65536、78125、46656、16807，最大是5⁷。"},{"id":210,"topic":"方程应用","question":"分钟转了一百园时针转了几圈 D Al","options":[{"id":"B","text":"2"},{"id":"C","text":"5/3"},{"id":"D","text":"3/4限 y"}],"answer":"C","explanation":"本题考查方程应用。设未知数，把题干中的等量关系翻译成方程并求解。计算结果为“5/3”，因此选择C。"},{"id":211,"topic":"比例百分数","question":"把90千克浓度为50%的酒精溶液稀释成30%，需要加水多少千克？","options":[{"id":"A","text":"54千克"},{"id":"B","text":"66千克"},{"id":"C","text":"72千克"},{"id":"D","text":"60千克"}],"answer":"D","explanation":"酒精质量保持45千克不变，稀释后总质量为45÷30%=150千克，因此需加水150-90=60千克。"},{"id":212,"topic":"比例百分数","question":"某企业调查网络信息获取方式，问卷回收率90%。使用搜索、官网、社交网站的分别有179、146、246人；三种都用115人，恰用两种24人，三种都不用52人。共发出多少份问卷？","options":[{"id":"A","text":"410份"},{"id":"B","text":"369份"},{"id":"C","text":"451份"},{"id":"D","text":"492份"}],"answer":"A","explanation":"三类人数和571=只用一种人数+2×24+3×115，得只用一种178人。回收问卷数为178+24+115+52=369，发出369÷90%=410份。"},{"id":213,"topic":"几何问题","question":"用一根周长相等的铁丝, 困城三角形、 园形、 正方形、 菊形, 则面积最大的图形是 ()","options":[{"id":"A","text":"三角形"},{"id":"B","text":"圆形 Cc. 正方形 D. BE"},{"id":"C","text":"以上都不正确"},{"id":"D","text":"以上都不正确"}],"answer":"B","explanation":"本题考查几何问题。画出关键尺寸，代入相应的周长、面积或体积公式。计算结果为“圆形 Cc. 正方形 D. BE”，因此选择B。"},{"id":214,"topic":"方程应用","question":"某工厂男职工人数是女职工的1/3，男职工比女职工少380人。全厂共有多少人？","options":[{"id":"A","text":"684人"},{"id":"B","text":"836人"},{"id":"C","text":"760人"},{"id":"D","text":"912人"}],"answer":"C","explanation":"设男职工x人、女职工3x人，3x-x=380，得x=190，总人数4x=760。"},{"id":215,"topic":"方程应用","question":"6, 18, () 78, 126","options":[{"id":"A","text":"40"},{"id":"B","text":"42"},{"id":"C","text":"44"},{"id":"D","text":"46"}],"answer":"B","explanation":"本题考查方程应用。设未知数，把题干中的等量关系翻译成方程并求解。计算结果为“42”，因此选择B。"},{"id":216,"topic":"数列规律","question":"找规律：6，-9，12，（ ），18。","options":[{"id":"A","text":"-15"},{"id":"B","text":"-17"},{"id":"C","text":"-13"},{"id":"D","text":"-11"}],"answer":"A","explanation":"绝对值依次加3，正负号交替，因此缺项为-15。"},{"id":217,"topic":"方程应用","question":"在一次联欢会上, 10名同学握手, 若每两人之间握一次手, 共握 () 次手","options":[{"id":"A","text":"28"},{"id":"B","text":"45"},{"id":"C","text":"36"},{"id":"D","text":"以上都不正确"}],"answer":"B","explanation":"本题考查方程应用。设未知数，把题干中的等量关系翻译成方程并求解。计算结果为“45”，因此选择B。"},{"id":218,"topic":"概率","question":"10个位置平均分给5个人，每人2个位置。随机放入3个红球，其余为白球。恰有3个人没拿到红球的概率是多少？","options":[{"id":"A","text":"0/3"},{"id":"B","text":"2/3"},{"id":"C","text":"1/3"},{"id":"D","text":"3/3"}],"answer":"C","explanation":"恰有3人无红球，表示3个红球集中在另外2人的4个位置且两人都拿到。选这2人有C(5,2)种，在4个位置选3个有4种，共40种；总数C(10,3)=120，概率1/3。"},{"id":219,"topic":"方程应用","question":"有一个两位数, 如果在两个数字中间加一个零, 得刻的三位数是原 S: 来的9倍, 请问这个两位数是 C)","options":[{"id":"A","text":"23"},{"id":"B","text":"34"},{"id":"C","text":"45"},{"id":"D","text":"56门心"}],"answer":"C","explanation":"本题考查方程应用。设未知数，把题干中的等量关系翻译成方程并求解。计算结果为“45”，因此选择C。"},{"id":220,"topic":"工程问题","question":"一项工作甲单独做20天，乙单独做30天。两人合作3天可完成全部工作的几分之几？","options":[{"id":"A","text":"1/4"},{"id":"B","text":"0/4"},{"id":"C","text":"2/4"},{"id":"D","text":"3/4"}],"answer":"A","explanation":"合作效率为1/20+1/30=1/12，3天完成3/12=1/4。"},{"id":221,"topic":"方程应用","question":"0.2、0.8、1.2和x的平均数为0.6，x是多少？","options":[{"id":"A","text":"0.1"},{"id":"B","text":"0.2"},{"id":"C","text":"0.3"},{"id":"D","text":"0.4"}],"answer":"B","explanation":"四个数总和应为0.6×4=2.4，前三个数和为2.2，所以x=0.2。"},{"id":222,"topic":"排列组合","question":"餐厅需要9升食用油。库房有15桶5升装、3桶2升装、8桶1升装。恰好发出9升有多少种发货方式？","options":[{"id":"A","text":"6种"},{"id":"B","text":"8种"},{"id":"C","text":"7种"},{"id":"D","text":"9种"}],"answer":"C","explanation":"列方程5a+2b+c=9。a=0时b可取0～3，共4种；a=1时b可取0～2，共3种，合计7种。"},{"id":223,"topic":"数列规律","question":"找规律：0，7，26，63，（ ）。","options":[{"id":"A","text":"112"},{"id":"B","text":"136"},{"id":"C","text":"148"},{"id":"D","text":"124"}],"answer":"D","explanation":"第n项为n³-1，下一项5³-1=124。"},{"id":224,"topic":"利润经济","question":"汉堡每个成本4.5元、售价10.5元，当天未售完即丢弃。10天每天制作200个，其中6天售完，4天各剩25个。10天共获利多少元？","options":[{"id":"A","text":"10950元"},{"id":"B","text":"9855元"},{"id":"C","text":"12045元"},{"id":"D","text":"13140元"}],"answer":"A","explanation":"共制作2000个，成本9000元；售出6×200+4×175=1900个，收入19950元，利润19950-9000=10950元。"},{"id":225,"topic":"方程应用","question":"若ab<0，则直线y=ax+b与x轴交点的位置一定是？","options":[{"id":"A","text":"x轴负半轴"},{"id":"B","text":"x轴正半轴"},{"id":"C","text":"y轴负半轴"},{"id":"D","text":"y轴正半轴"}],"answer":"B","explanation":"令y=0得横坐标x=-b/a。ab<0说明a、b异号，所以-b/a>0，交点在x轴正半轴。"},{"id":226,"topic":"方程应用","question":"计算：(1-1/10)(1-1/9)(1-1/8)…(1-1/2)。","options":[{"id":"A","text":"0/10"},{"id":"B","text":"2/10"},{"id":"C","text":"1/10"},{"id":"D","text":"3/10"}],"answer":"C","explanation":"写成9/10×8/9×7/8×…×1/2，中间因子全部约去，只剩1/10。"},{"id":227,"topic":"年龄问题","question":"10年前父亲年龄是女儿的7倍，15年后父亲年龄是女儿的2倍。女儿现在多少岁？","options":[{"id":"A","text":"13岁"},{"id":"B","text":"17岁"},{"id":"C","text":"19岁"},{"id":"D","text":"15岁"}],"answer":"D","explanation":"设现在父亲F岁、女儿D岁。F-10=7(D-10)，F+15=2(D+15)，联立得D=15、F=45。"},{"id":228,"topic":"行程问题","question":"比例尺1∶100000的地图上，两地距离13.8厘米，实际距离是多少千米？","options":[{"id":"A","text":"13.8千米"},{"id":"B","text":"12.42千米"},{"id":"C","text":"15.18千米"},{"id":"D","text":"16.56千米"}],"answer":"A","explanation":"13.8×100000厘米=1380000厘米=13.8千米。"},{"id":229,"topic":"方程应用","question":"乒乓球比赛中每两名选手赛一场，共36场。参赛者有多少人？","options":[{"id":"A","text":"8人"},{"id":"B","text":"9人"},{"id":"C","text":"10人"},{"id":"D","text":"11人"}],"answer":"B","explanation":"设n人，比赛场数C(n,2)=36，即n(n-1)=72，解得n=9。"},{"id":230,"topic":"数列规律","question":"按规律：1=5，2=15，3=215，4=2145，那么5=？","options":[{"id":"A","text":"19337"},{"id":"B","text":"23633"},{"id":"C","text":"21485"},{"id":"D","text":"25781"}],"answer":"C","explanation":"右侧每次在倒数第二位前插入下一个2的幂：1、2、4、8，因此得到21485。"},{"id":231,"topic":"利润经济","question":"商店规定购买标价200元以上商品可优惠20%。用300元最多可以买到标价多少元的商品？","options":[{"id":"A","text":"337元"},{"id":"B","text":"413元"},{"id":"C","text":"451元"},{"id":"D","text":"375元"}],"answer":"D","explanation":"实付为标价的80%，标价上限为300÷0.8=375元。"},{"id":232,"topic":"比例百分数","question":"食堂购进200斤含水量90%的西红柿。3天后含水量变为80%，这批西红柿总重量减少多少斤？","options":[{"id":"A","text":"100斤"},{"id":"B","text":"90斤"},{"id":"C","text":"110斤"},{"id":"D","text":"120斤"}],"answer":"A","explanation":"不变的固体物质原有200×10%=20斤。含水量80%时固体占20%，总重为20÷20%=100斤，因此减少100斤。"},{"id":233,"topic":"概率","question":"一个家庭有两个孩子，已知至少有一个是女孩。假定生男生女概率相同，两个孩子都是女孩的概率是多少？","options":[{"id":"A","text":"0/3"},{"id":"B","text":"1/3"},{"id":"C","text":"2/3"},{"id":"D","text":"3/3"}],"answer":"B","explanation":"满足“至少一个女孩”的等可能性别组合是女女、女男、男女三种，其中只有女女符合，所以概率为1/3。"},{"id":234,"topic":"容斥原理","question":"红、黄、蓝珠子各若干。52名学生每人取1～3颗，每种颜色至多取1颗。至少有多少人取珠方式完全相同？","options":[{"id":"A","text":"7人"},{"id":"B","text":"9人"},{"id":"C","text":"8人"},{"id":"D","text":"10人"}],"answer":"C","explanation":"取法共有C(3,1)+C(3,2)+C(3,3)=7种。52÷7=7余3，由抽屉原理至少有8人相同。"},{"id":235,"topic":"方程应用","question":"牧场养27头牛，6天吃完草；养23头牛，9天吃完。草持续生长。养21头牛多少天吃完？","options":[{"id":"A","text":"11天"},{"id":"B","text":"13天"},{"id":"C","text":"14天"},{"id":"D","text":"12天"}],"answer":"D","explanation":"设每天长草量相当于r头牛，初始草量G。6(27-r)=9(23-r)，得r=15、G=72；21头牛净消耗6份/天，需72÷6=12天。"},{"id":236,"topic":"方程应用","question":"甲乙丙丁四人为地震灾区捐款, 甲捐款数是另外三人捐款总数的一半, 乙抹全款数是另外三人捐款总数的三分之一, 丙捐款数是古外三人捐款总数的四分之一, 丁捐款169元, 请问四人一共捐款多少钱?","options":[{"id":"A","text":"780"},{"id":"B","text":"890"},{"id":"C","text":"1183"},{"id":"D","text":"2083... a"}],"answer":"A","explanation":"本题考查方程应用。设未知数，把题干中的等量关系翻译成方程并求解。计算结果为“780”，因此选择A。"},{"id":237,"topic":"方程应用","question":"1992是24个连续偶数的和，其中最大的偶数是多少？","options":[{"id":"A","text":"95"},{"id":"B","text":"106"},{"id":"C","text":"117"},{"id":"D","text":"128"}],"answer":"B","explanation":"平均数为1992÷24=83。24个连续偶数关于83对称，最小60、最大106。"},{"id":238,"topic":"数论问题","question":"以下哪个数字能被11整除? &","options":[{"id":"A","text":"937845678 or"},{"id":"B","text":"235789453 E"},{"id":"C","text":"436728839"},{"id":"D","text":"867392267"}],"answer":"A","explanation":"本题考查数论问题。把整除与余数条件写成同余式，再寻找最小公倍关系。计算结果为“937845678 or”，因此选择A。"},{"id":239,"topic":"工程问题","question":"道路抢修规定d天完成。甲单独做恰好按期，乙单独做需d+3天。两队合作2天后，余下由乙单独完成，仍恰好按期。d是多少？","options":[{"id":"A","text":"5天"},{"id":"B","text":"7天"},{"id":"C","text":"8天"},{"id":"D","text":"6天"}],"answer":"D","explanation":"列式2(1/d+1/(d+3))+(d-2)/(d+3)=1，化简得d=6。"},{"id":240,"topic":"数列规律","question":"找规律：1，5，（ ），29。","options":[{"id":"A","text":"13"},{"id":"B","text":"12"},{"id":"C","text":"14"},{"id":"D","text":"15"}],"answer":"A","explanation":"相邻差依次为4、8、16，后一差是前一差的2倍，所以缺项为5+8=13。"},{"id":241,"topic":"方程应用","question":"据估计, 东京市居民的年用水里为2亿吨, 大约有6000万吨水用在冲水马柚。 为节约用水, 东京某居民在自己楼房顶安装了一个容积为2吨的储水罐储存两水用于冲马桶,15年来即便在少一季节, 罐内一水从木用尽过。 他认为, 若东京每户居民都装一个2吨的储水罐, 就相当于在市内建起一个容积为900万吨的水库。 由此可以推出东京居民每户年用水量为 ()。","options":[{"id":"A","text":"40~50 MiB, 50~60吨"},{"id":"C","text":"30~40 mi"},{"id":"D","text":"60-~70"}],"answer":"A","explanation":"本题考查方程应用。设未知数，把题干中的等量关系翻译成方程并求解。计算结果为“40~50 MiB, 50~60吨”，因此选择A。"},{"id":242,"topic":"方程应用","question":"两个水梓共盛30升水, 如果把第一个桶里的6厂水倒入第二个水 it 梓里, 两个水桶的水就一样多, 问第二桶水重多少厂?","options":[{"id":"A","text":"8"},{"id":"B","text":"21"},{"id":"C","text":"9"},{"id":"D","text":"10 b"}],"answer":"C","explanation":"本题考查方程应用。设未知数，把题干中的等量关系翻译成方程并求解。计算结果为“9”，因此选择C。"},{"id":243,"topic":"数论问题","question":"下列哪个数既能被3整除，又是4的倍数？","options":[{"id":"A","text":"303"},{"id":"B","text":"307"},{"id":"C","text":"308"},{"id":"D","text":"312"}],"answer":"D","explanation":"同时满足两个条件即能被12整除。312÷12=26，其他选项不满足。"},{"id":244,"topic":"比例百分数","question":"甲把自己原有数量的一半给乙后，乙现有数量是甲现有数量的4/3。甲、乙原有数量之比是多少？","options":[{"id":"A","text":"6∶1"},{"id":"B","text":"5∶1"},{"id":"C","text":"7∶1"},{"id":"D","text":"8∶1"}],"answer":"A","explanation":"设甲原有6份、乙原有1份。甲给出3份后剩3份，乙变为4份，恰是甲现有量的4/3，所以原比为6∶1。"},{"id":245,"topic":"方程应用","question":"甲队每小时修12米，比乙队每小时多修1/3。两队合修1小时共修多少米？","options":[{"id":"A","text":"19米"},{"id":"B","text":"21米"},{"id":"C","text":"23米"},{"id":"D","text":"25米"}],"answer":"B","explanation":"乙队效率为12÷(1+1/3)=9米/时，两队合计12+9=21米。"},{"id":246,"topic":"计数问题","question":"李主任8:30后参加会议。会议开始时手表时针与分针夹角为120°，结束时为180°。会议期间两针呈90°的情况最多出现几次？","options":[{"id":"A","text":"3次"},{"id":"B","text":"5次"},{"id":"C","text":"4次"},{"id":"D","text":"6次"}],"answer":"C","explanation":"时针和分针的相对角速度恒定。结合开始、结束夹角以及会议位于上午的时间范围，分段枚举两针夹角为90°的时刻，最多出现4次。"},{"id":247,"topic":"概率","question":"某单位有3项业务要招标, 共有5家公司前来投标, 且每家公司都对3项业史务发出了投标中请, 最终发现每项业务都有且只有1家公司中标。 如5家公司圭各项业务中中标的概率均相等, 问这3项业务由同一家公司中标的概率为多少?","options":[{"id":"A","text":"1/86"},{"id":"B","text":"1/8L ="},{"id":"C","text":"1/125 i. 1/243"},{"id":"D","text":"以上都不正确"}],"answer":"A","explanation":"本题考查概率。先确定所有等可能结果，再统计满足条件的结果数，用“符合数÷总数”计算。计算结果为“1/86”，因此选择A。"},{"id":248,"topic":"排列组合","question":"黄、白、蓝三个不同颜色的球从左到右排列，有多少种不同排法？","options":[{"id":"A","text":"6种"},{"id":"B","text":"5种"},{"id":"C","text":"7种"},{"id":"D","text":"8种"}],"answer":"A","explanation":"三个不同元素的全排列数为3!=6。"},{"id":249,"topic":"数论问题","question":"5649879、98798742、78668、54678这四个数中，能被9整除的有几个？","options":[{"id":"A","text":"0个"},{"id":"B","text":"1个"},{"id":"C","text":"2个"},{"id":"D","text":"3个"}],"answer":"B","explanation":"各数数字和分别为48、54、35、30，只有54能被9整除，所以只有1个。"},{"id":250,"topic":"几何问题","question":"直径分别为1、2、3、4、5、8厘米的圆片中，周长最小的圆片周长是多少？","options":[{"id":"A","text":"π厘米"},{"id":"B","text":"2π厘米"},{"id":"C","text":"3π厘米"},{"id":"D","text":"4π厘米"}],"answer":"A","explanation":"圆周长C=πd，直径最小为1厘米，所以最小周长为π厘米。"},{"id":251,"topic":"方程应用","question":"语文、数学、英语三本书价格比为2∶5∶3，总价70元。数学书多少元？","options":[{"id":"A","text":"31元"},{"id":"B","text":"39元"},{"id":"C","text":"43元"},{"id":"D","text":"35元"}],"answer":"D","explanation":"总份数10，数学占5份，价格70×5/10=35元。"},{"id":252,"topic":"容斥原理","question":"“甲、乙两人至少有一人不是大学生”等价于哪一项？","options":[{"id":"A","text":"甲、乙至多一人是大学生"},{"id":"B","text":"甲、乙都不是大学生"},{"id":"C","text":"甲是大学生而乙不是"},{"id":"D","text":"甲、乙至少一人是大学生"}],"answer":"A","explanation":"“至少一人不是”否定的是“两人都是大学生”，等价于大学生人数不超过1。"},{"id":253,"topic":"概率","question":"某病自然痊愈率0.1。无效新药给10名病人服用，至少3人痊愈就误判有效。发生误判的概率是多少？","options":[{"id":"A","text":"约0.0194"},{"id":"B","text":"约0.0520"},{"id":"C","text":"约0.0702"},{"id":"D","text":"约0.1000"}],"answer":"C","explanation":"令X服从B(10,0.1)，误判概率P(X≥3)=1-P(0)-P(1)-P(2)≈0.0702。"},{"id":254,"topic":"方程应用","question":"所有两位偶数的和是多少？","options":[{"id":"A","text":"2187"},{"id":"B","text":"2673"},{"id":"C","text":"2430"},{"id":"D","text":"2916"}],"answer":"C","explanation":"两位偶数从10到98，共45个，平均数54，总和45×54=2430。"},{"id":255,"topic":"概率","question":"连续掷一枚均匀骰子两次，点数和为7的概率是多少？","options":[{"id":"A","text":"0/6"},{"id":"B","text":"2/6"},{"id":"C","text":"3/6"},{"id":"D","text":"1/6"}],"answer":"D","explanation":"共有36种等可能结果，和为7的有(1,6)、(2,5)、…、(6,1)共6种，概率6/36=1/6。"},{"id":256,"topic":"方程应用","question":"公共汽车起点站每5分钟一赵车, 一小时要发出多少辆公共汽车 () at","options":[{"id":"A","text":"12"},{"id":"B","text":"13"},{"id":"C","text":"28"},{"id":"D","text":"30 ah"}],"answer":"B","explanation":"本题考查方程应用。设未知数，把题干中的等量关系翻译成方程并求解。计算结果为“13”，因此选择B。"},{"id":257,"topic":"比例百分数","question":"李继工资的60%是900 - 元, 她这个月工资为 (1500元) 271.3, 4, 8, 24, 88()","options":[{"id":"A","text":"121"},{"id":"B","text":"196"},{"id":"C","text":"225"},{"id":"D","text":"344"}],"answer":"B","explanation":"本题考查比例百分数。把基准量设为1份或100%，按对应比例换算。计算结果为“196”，因此选择B。"},{"id":258,"topic":"方程应用","question":"张鹏每周储茜35元, 他已有100元存款, 还帮多少天才能买240元的自行转?","options":[{"id":"A","text":"4"},{"id":"B","text":"6"},{"id":"C","text":"28"},{"id":"D","text":"21"}],"answer":"C","explanation":"本题考查方程应用。设未知数，把题干中的等量关系翻译成方程并求解。计算结果为“28”，因此选择C。"},{"id":259,"topic":"方程应用","question":"已知a/b=2/3，求(2a+b)/(3b)。","options":[{"id":"A","text":"6/9"},{"id":"B","text":"8/9"},{"id":"C","text":"9/9"},{"id":"D","text":"7/9"}],"answer":"D","explanation":"令a=2k、b=3k，则(2a+b)/(3b)=(4k+3k)/(9k)=7/9。"},{"id":260,"topic":"方程应用","question":"(904-594)÷620等于多少？","options":[{"id":"A","text":"1/2"},{"id":"B","text":"0/2"},{"id":"C","text":"2/2"},{"id":"D","text":"3/2"}],"answer":"A","explanation":"904-594=310，310÷620=1/2。"},{"id":261,"topic":"比例百分数","question":"某运动员跳高成绩2.3米，跳远成绩是跳高成绩2.5倍的80%。跳远成绩是多少米？","options":[{"id":"A","text":"4.14米"},{"id":"B","text":"4.6米"},{"id":"C","text":"5.06米"},{"id":"D","text":"5.52米"}],"answer":"B","explanation":"2.3×2.5×80%=2.3×2=4.6米。"},{"id":262,"topic":"比例百分数","question":"某学校目前学生与教师人数之比为30:1。若学生增加50人、教师增加5人，两者之比变为25:1。目前教师有多少人？","options":[{"id":"A","text":"8"},{"id":"B","text":"10"},{"id":"C","text":"12"},{"id":"D","text":"15"}],"answer":"D","explanation":"设目前教师有x人，则(30x+50)/(x+5)=25，解得x=15。"},{"id":263,"topic":"方程应用","question":"整数x与y的积是偶数，和是奇数。x、y的奇偶性如何？","options":[{"id":"A","text":"均为偶数"},{"id":"B","text":"均为奇数"},{"id":"C","text":"一奇一偶"},{"id":"D","text":"无法确定"}],"answer":"C","explanation":"和为奇数说明两数奇偶性不同；一奇一偶的乘积必为偶数，与题意一致。"},{"id":264,"topic":"比例百分数","question":"一批商品先涨价20%, 再降价10%, 问现在价格是多少?","options":[{"id":"A","text":"提高了"},{"id":"B","text":"降低了"},{"id":"C","text":"不变"},{"id":"D","text":"无法确定"}],"answer":"A","explanation":"本题考查比例百分数。把基准量设为1份或100%，按对应比例换算。计算结果为“提高了”，因此选择A。"},{"id":265,"topic":"方程应用","question":"5个不同的数，两两之和依次为3、4、5、6、7、8、11、12、13、15。这5个数的平均值是多少？","options":[{"id":"A","text":"3.78"},{"id":"B","text":"4.2"},{"id":"C","text":"4.62"},{"id":"D","text":"5.04"}],"answer":"B","explanation":"10个两两之和的总和为84。每个原数在两两和中出现4次，所以5个数之和为84÷4=21，平均值21÷5=4.2。"},{"id":266,"topic":"概率","question":"任取一个自然数, 则该数平方的末尾数是4的概率为 () N05","options":[{"id":"B","text":"0.2/"},{"id":"C","text":"04"}],"answer":"B","explanation":"本题考查概率。先确定所有等可能结果，再统计满足条件的结果数，用“符合数÷总数”计算。计算结果为“0.2/”，因此选择B。"},{"id":267,"topic":"概率","question":"15000件产品中有1000件废品，随机抽取150件，废品数的期望是多少？","options":[{"id":"A","text":"9件"},{"id":"B","text":"11件"},{"id":"C","text":"12件"},{"id":"D","text":"10件"}],"answer":"D","explanation":"期望=抽样数×总体废品率=150×1000/15000=10。"},{"id":268,"topic":"工程问题","question":"甲、乙合作5天完成一项工程，甲、乙、丙合作3天完成。丙单独做需多少天？","options":[{"id":"A","text":"7.5天"},{"id":"B","text":"6.75天"},{"id":"C","text":"8.25天"},{"id":"D","text":"9天"}],"answer":"A","explanation":"丙的效率为1/3-1/5=2/15，因此单独完成需15/2=7.5天。"},{"id":269,"topic":"容斥原理","question":"袋中有红、白、黄、蓝4种颜色的球。至少取多少个，才能保证有2个球颜色相同？","options":[{"id":"A","text":"4个"},{"id":"B","text":"5个"},{"id":"C","text":"6个"},{"id":"D","text":"7个"}],"answer":"B","explanation":"最不利情况先取到4种不同颜色，第5个必与其中一种同色。"},{"id":270,"topic":"方程应用","question":"关于三个连续整数：①它们的和一定是偶数；②它们的乘积一定是偶数。正确的是？","options":[{"id":"A","text":"只有①正确"},{"id":"B","text":"只有②正确"},{"id":"C","text":"①②都正确"},{"id":"D","text":"①②都不正确"}],"answer":"B","explanation":"三个连续整数中必有一个偶数，所以乘积一定为偶数；和的奇偶性与中间整数相同，不一定为偶数。"},{"id":271,"topic":"概率","question":"15000件产品中有1000件次品，随机抽取150件检查，查得次品数的数学期望是多少？","options":[{"id":"A","text":"9件"},{"id":"B","text":"11件"},{"id":"C","text":"12件"},{"id":"D","text":"10件"}],"answer":"D","explanation":"超几何分布期望为样本量×总体次品率，即150×1000/15000=10。"},{"id":272,"topic":"概率","question":"公务员考试分笔试和面试, 笔试通过率为20%, 最后的录取率为4%; 己知桦人已经通过笔试, 则他最后被录取的概率为 (》","options":[{"id":"A","text":"20%"},{"id":"B","text":"24%"},{"id":"C","text":"16%"},{"id":"D","text":"4% a"}],"answer":"A","explanation":"本题考查概率。先确定所有等可能结果，再统计满足条件的结果数，用“符合数÷总数”计算。计算结果为“20%”，因此选择A。"},{"id":273,"topic":"方程应用","question":"若甲数加3与乙数减8相等，甲数比乙数少多少？","options":[{"id":"A","text":"10"},{"id":"B","text":"11"},{"id":"C","text":"12"},{"id":"D","text":"13"}],"answer":"B","explanation":"甲+3=乙-8，移项得乙-甲=11。"},{"id":274,"topic":"方程应用","question":"在200米小路一侧栽树，每隔40米一棵，两端都栽，共栽多少棵？","options":[{"id":"A","text":"5棵"},{"id":"B","text":"7棵"},{"id":"C","text":"6棵"},{"id":"D","text":"8棵"}],"answer":"C","explanation":"200÷40=5个间隔，两端都栽时棵数为5+1=6。"},{"id":275,"topic":"概率","question":"从3、5、7、11四个质数中任取两个相乘，可以得到多少个不同的积？","options":[{"id":"A","text":"5个"},{"id":"B","text":"7个"},{"id":"C","text":"8个"},{"id":"D","text":"6个"}],"answer":"D","explanation":"任取两个质数的组合数为C(4,2)=6，且不同质数对的乘积不会相同。"},{"id":276,"topic":"方程应用","question":"象棋比赛每两位棋手赛一局，共36局。参赛棋手有多少人？","options":[{"id":"A","text":"9人"},{"id":"B","text":"8人"},{"id":"C","text":"10人"},{"id":"D","text":"11人"}],"answer":"A","explanation":"C(n,2)=36，解得n=9。"},{"id":277,"topic":"几何问题","question":"物体沿圆周运行一圈半，共转过多少度？","options":[{"id":"A","text":"486°"},{"id":"B","text":"540°"},{"id":"C","text":"594°"},{"id":"D","text":"648°"}],"answer":"B","explanation":"一圈360°，一圈半为360×1.5=540°。"},{"id":278,"topic":"年龄问题","question":"甲年龄等于乙现在年龄时，乙4岁；乙年龄等于甲现在年龄时，甲67岁。甲、乙现在各多少岁？","options":[{"id":"A","text":"甲42岁、乙21岁"},{"id":"B","text":"甲46岁、乙25岁"},{"id":"C","text":"甲48岁、乙27岁"},{"id":"D","text":"甲50岁、乙29岁"}],"answer":"B","explanation":"设年龄差d，则乙=d+4、甲=2d+4；又67-甲=d，解得d=21，所以甲46岁、乙25岁。"},{"id":279,"topic":"方程应用","question":"正常情况下，12小时内时针和分针重合多少次？","options":[{"id":"A","text":"10次"},{"id":"B","text":"12次"},{"id":"C","text":"13次"},{"id":"D","text":"11次"}],"answer":"D","explanation":"分针相对时针每12/11小时追上一圈，因此12小时内重合11次。"},{"id":280,"topic":"概率","question":"10件产品中有4件不合格。随机取2件，已知其中1件不合格，另一件也不合格的概率是多少？","options":[{"id":"A","text":"1/3"},{"id":"B","text":"0/3"},{"id":"C","text":"2/3"},{"id":"D","text":"3/3"}],"answer":"A","explanation":"发现并拿出1件不合格品后，剩余9件中有3件不合格，因此另一件也不合格的概率为3/9=1/3。"},{"id":281,"topic":"计数问题","question":"某月1—12日安排甲、乙、丙值夜班，每人4天，三人各自值班日期之和相等。已知甲值1、2日，乙值9、10日。丙第一次与最后一次值班之间最多有几天不值班？","options":[{"id":"A","text":"5天"},{"id":"B","text":"6天"},{"id":"C","text":"7天"},{"id":"D","text":"8天"}],"answer":"B","explanation":"先由1到12日期总和78，得每人日期和26；再按甲、乙已知日期补足各自另外两天并枚举，丙首末值班日的最大空档为6天。"},{"id":282,"topic":"容斥原理","question":"一个学雷锋小组现有14人，每人每天打工可挣3元。到11月11日已挣1764元，计划在12月9日达到3000元。新增的1人至少需要工作多少天？","options":[{"id":"A","text":"18天"},{"id":"B","text":"22天"},{"id":"C","text":"20天"},{"id":"D","text":"24天"}],"answer":"C","explanation":"剩余28天需挣1236元。原14人做28天可挣1176元，还差60元；新增1人每天多挣3元，因此至少需要工作60÷3=20天。"},{"id":283,"topic":"比例百分数","question":"林场第一年造林80亩，以后每年比前一年多20%。第二年造林多少亩？","options":[{"id":"A","text":"86亩"},{"id":"B","text":"106亩"},{"id":"C","text":"116亩"},{"id":"D","text":"96亩"}],"answer":"D","explanation":"80×(1+20%)=96亩。"},{"id":284,"topic":"计数问题","question":"小区道路两侧各栽35棵树。一侧每3棵银杏后栽1棵梧桐，另一侧每4棵梧桐后栽1棵银杏。合理安排首尾后，最多可栽多少棵银杏？","options":[{"id":"A","text":"34棵"},{"id":"B","text":"31棵"},{"id":"C","text":"37棵"},{"id":"D","text":"40棵"}],"answer":"A","explanation":"分别按3∶1和1∶4的循环排列，并利用首尾可先放银杏的余量。两侧银杏数相加最多为34棵。"},{"id":285,"topic":"比例百分数","question":"小王将12600元存入年利率7.25%的银行。若改存年利率6.5%的银行，一年少得多少利息？","options":[{"id":"A","text":"85.05元"},{"id":"B","text":"94.5元"},{"id":"C","text":"103.95元"},{"id":"D","text":"113.4元"}],"answer":"B","explanation":"年利率相差0.75%，少得利息为12600×0.75%=94.5元。"},{"id":286,"topic":"行程问题","question":"甲、乙从A地到B地分别需40分钟和30分钟。甲早出发5分钟，乙出发后多少分钟追上甲？","options":[{"id":"A","text":"13分钟"},{"id":"B","text":"17分钟"},{"id":"C","text":"15分钟"},{"id":"D","text":"19分钟"}],"answer":"C","explanation":"设乙走t分钟追上，路程比例满足(t+5)/40=t/30，解得t=15。"},{"id":287,"topic":"比例百分数","question":"老王两年前买入一件艺术品，现市价上涨50%。他按现市价八折卖出，并支付成交价5%的费用，最终比买入时多得7万元。买入价是多少？","options":[{"id":"A","text":"45万元"},{"id":"B","text":"55万元"},{"id":"C","text":"60万元"},{"id":"D","text":"50万元"}],"answer":"D","explanation":"设买入价x万元。净到手为1.5x×0.8×0.95=1.14x，利润0.14x=7，解得x=50万元。"},{"id":288,"topic":"方程应用","question":"一条大街长7200米，从起点到终点共设9个车站，平均相邻两站相距多少米？","options":[{"id":"A","text":"900米"},{"id":"B","text":"810米"},{"id":"C","text":"990米"},{"id":"D","text":"1080米"}],"answer":"A","explanation":"9个车站形成8个间隔，7200÷8=900米。"},{"id":289,"topic":"排列组合","question":"自行车前轴齿轮齿数为48、36、24，后轴为36、24、16、12。可获得多少种不同的传动比？","options":[{"id":"A","text":"7种"},{"id":"B","text":"8种"},{"id":"C","text":"9种"},{"id":"D","text":"10种"}],"answer":"B","explanation":"列出12个前后齿数比并约分，去掉重复后共有2/3、1、4/3、3/2、2、9/4、3、4八种。"},{"id":290,"topic":"年龄问题","question":"一位百岁老人出生于20世纪。2015年年龄数字和是2012年年龄数字和的1/3（出生年算0岁）。出生年份各数字之和是多少？","options":[{"id":"A","text":"13"},{"id":"B","text":"15"},{"id":"C","text":"14"},{"id":"D","text":"16"}],"answer":"C","explanation":"在百岁范围内检验可得老人出生于1904年：2015年111岁，数字和3；2012年108岁，数字和9。出生年数字和为1+9+0+4=14。"},{"id":291,"topic":"行程问题","question":"A到B为下坡。小周6:00从A出发，7:00到中点C；到B后立即返回，10:00再次到C。随后速度提高1米/秒，11:30回到A。AB距离在哪个范围？","options":[{"id":"A","text":"小于30公里"},{"id":"B","text":"30～40公里"},{"id":"C","text":"40～50公里"},{"id":"D","text":"大于50公里"}],"answer":"C","explanation":"下坡1小时走半程，8:00到B；上坡B到C用2小时，原上坡速度为下坡一半。后半程1.5小时走完，提速3.6千米/时。由D/3-D/4=3.6得D=43.2千米。"},{"id":292,"topic":"方程应用","question":"某班男、女生人数比为2∶1，转入2名女生后变为3∶2。现在全班多少人？","options":[{"id":"A","text":"20人"},{"id":"B","text":"18人"},{"id":"C","text":"22人"},{"id":"D","text":"24人"}],"answer":"A","explanation":"设原女生k人、男生2k人。2k/(k+2)=3/2，解得k=6；现在总人数12+8=20。"},{"id":293,"topic":"数列规律","question":"找规律：0，7，26，63，（ ），215。","options":[{"id":"A","text":"112"},{"id":"B","text":"124"},{"id":"C","text":"136"},{"id":"D","text":"148"}],"answer":"B","explanation":"各项为n³-1，缺项是5³-1=124，后一项6³-1=215。"},{"id":294,"topic":"数列规律","question":"找规律：3，6，（ ），21，33。","options":[{"id":"A","text":"11"},{"id":"B","text":"13"},{"id":"C","text":"12"},{"id":"D","text":"14"}],"answer":"C","explanation":"相邻差依次为3、6、9、12，因此缺项是6+6=12。"},{"id":295,"topic":"比例百分数","question":"用8%和5%的盐水配制600克7%的盐水，两种盐水各需多少克？","options":[{"id":"A","text":"7%盐水400克、5%盐水200克"},{"id":"B","text":"9%盐水400克、5%盐水200克"},{"id":"C","text":"10%盐水400克、5%盐水200克"},{"id":"D","text":"8%盐水400克、5%盐水200克"}],"answer":"D","explanation":"设8%盐水x克，则0.08x+0.05(600-x)=0.07×600，解得x=400。"},{"id":296,"topic":"利润经济","question":"商品成本40元，按标价打八折后的售价仍比成本高25%。商品标价是多少？","options":[{"id":"A","text":"62.5元"},{"id":"B","text":"56.25元"},{"id":"C","text":"68.75元"},{"id":"D","text":"75元"}],"answer":"A","explanation":"打折后的售价为40×1.25=50元，标价=50÷0.8=62.5元。"},{"id":297,"topic":"行程问题","question":"汽车往返甲乙两地，去程时速30千米，回程时速60千米。往返平均速度是多少？","options":[{"id":"A","text":"36千米/时"},{"id":"B","text":"40千米/时"},{"id":"C","text":"44千米/时"},{"id":"D","text":"48千米/时"}],"answer":"B","explanation":"设单程距离d，总路程2d，总时间d/30+d/60=d/20，所以平均速度2d÷(d/20)=40千米/时。"},{"id":298,"topic":"方程应用","question":"下面4个数中, 恰有一个数是两个相邻整数的乘积, 这个数是 () ‘","options":[{"id":"A","text":"5096303"},{"id":"B","text":"5096304"},{"id":"C","text":"5096805"},{"id":"D","text":"5096306"}],"answer":"D","explanation":"本题考查方程应用。设未知数，把题干中的等量关系翻译成方程并求解。计算结果为“5096306”，因此选择D。"},{"id":299,"topic":"工程问题","question":"某集团有A、B两个公司，A公司全年销售任务是B公司的1.2倍；前三季度B公司的销售业绩是A公司的1.2倍。若按前三季度平均销售业绩计算，B公司到年底恰好完成任务。若A公司希望完成全年任务，第四季度销售业绩需达到前三季度平均销售业绩的多少倍？","options":[{"id":"A","text":"1.44"},{"id":"B","text":"2.4"},{"id":"C","text":"2.76"},{"id":"D","text":"3.88"}],"answer":"C","explanation":"设B公司全年任务为T，A公司前三季度平均每季度业绩为a，则4×1.2a=T。A公司前三季度完成3a，第四季度需完成1.2T-3a=2.76a。"},{"id":300,"topic":"工程问题","question":"4台车床每小时共加工180个零件。若增加3台同效率的车床，每小时共能加工多少个零件？","options":[{"id":"A","text":"300"},{"id":"B","text":"315"},{"id":"C","text":"350"},{"id":"D","text":"415"}],"answer":"B","explanation":"每台每小时加工180÷4=45个，7台共加工45×7=315个。"},{"id":301,"topic":"方程应用","question":"甲、乙两队共100人。甲队调出本队1/4到乙队后，乙队比甲队多10人。甲队原有多少人？","options":[{"id":"A","text":"54人"},{"id":"B","text":"60人"},{"id":"C","text":"66人"},{"id":"D","text":"72人"}],"answer":"B","explanation":"设甲原有x人。调整后甲3x/4，乙100-3x/4，差为10，解得x=60。"},{"id":302,"topic":"方程应用","question":"若A>B，且A、B、C均为正数，下列结论中一定错误的是哪一项？","options":[{"id":"A","text":"AB>BC"},{"id":"B","text":"A+C>B+C"},{"id":"C","text":"C-A>C-B"},{"id":"D","text":"A/B>B/C"}],"answer":"C","explanation":"A>B，两边同乘-1得-A<-B，再同时加C，得C-A<C-B，所以选项C一定错误。"},{"id":303,"topic":"行程问题","question":"某人在15分钟内能打X个字，按同样的速度打完Y个字需要多少小时？","options":[{"id":"A","text":"15Y/X"},{"id":"B","text":"X/(15Y)"},{"id":"C","text":"4X/Y"},{"id":"D","text":"Y/(4X)"}],"answer":"D","explanation":"15分钟为1/4小时，速度为每小时4X个字，因此所需时间为Y/(4X)小时。"},{"id":304,"topic":"数论问题","question":"一本小说第一天读全书4/7，第二天读余下的3/5，还剩42页。全书多少页？","options":[{"id":"A","text":"245页"},{"id":"B","text":"221页"},{"id":"C","text":"269页"},{"id":"D","text":"293页"}],"answer":"A","explanation":"剩余比例为(3/7)×(2/5)=6/35，全书42÷(6/35)=245页。"},{"id":305,"topic":"数列规律","question":"找规律：2.5，1.25，0.625，（ ），0.15625。","options":[{"id":"A","text":"0.2125"},{"id":"B","text":"0.3125"},{"id":"C","text":"0.4125"},{"id":"D","text":"0.5125"}],"answer":"B","explanation":"每项都是前一项除以2，0.625÷2=0.3125。"},{"id":306,"topic":"数列规律","question":"找规律：18，42，78，126，（ ）。","options":[{"id":"A","text":"167"},{"id":"B","text":"205"},{"id":"C","text":"186"},{"id":"D","text":"224"}],"answer":"C","explanation":"相邻差为24、36、48，依次增加12，下一差为60，所以126+60=186。"},{"id":307,"topic":"数列规律","question":"345，268，349，264，353，260，357，（ ）。","options":[{"id":"A","text":"370"},{"id":"B","text":"360"},{"id":"C","text":"255"},{"id":"D","text":"256"}],"answer":"D","explanation":"奇数项依次加4，偶数项依次减4，因此下一偶数项为256。"},{"id":308,"topic":"方程应用","question":"比较579/580、1427/1428和42/43的大小。","options":[{"id":"A","text":"1427/1428＞579/580＞42/43"},{"id":"B","text":"579/580＞1427/1428＞42/43"},{"id":"C","text":"42/43＞579/580＞1427/1428"},{"id":"D","text":"579/580＞42/43＞1427/1428"}],"answer":"A","explanation":"都写成1减单位分数。减去的1/1428最小，1/580次之，1/43最大，因此顺序如答案。"}];
